def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: int number of nanoseconds since midnight
    :param tz: optional timezone information (datetime.tzinfo or offset string)
    :return: datetime.time
    """
    # Validate nanoseconds
    try:
        if nanoseconds is None:
            raise TypeError("nanoseconds cannot be None")
        if not isinstance(nanoseconds, int):
            nanoseconds = int(nanoseconds)
        if nanoseconds < 0:
            raise ValueError("nanoseconds must be non-negative")
    except Exception as exc:
        raise ValueError(f"Invalid nanoseconds value: {nanoseconds}") from exc

    # Normalize to a single day
    nanoseconds %= 24 * 60 * 60 * 1_000_000_000

    total_seconds = nanoseconds // 1_000_000_000
    remaining_ns = nanoseconds % 1_000_000_000
    microseconds = remaining_ns // 1_000

    hour = total_seconds // 3600
    minute = (total_seconds % 3600) // 60
    second = total_seconds % 60

    # Handle timezone
    tzinfo = None
    if tz is not None:
        # If tz is already a tzinfo instance
        if hasattr(tz, "utcoffset"):
            tzinfo = tz
        else:
            # Try to parse a string offset like "+02:00" or "-05:30"
            try:
                s = str(tz).strip()
                if s[0] in ('+', '-'):
                    sign = 1 if s[0] == '+' else -1
                    parts = s[1:].split(':')
                    if len(parts) != 2:
                        raise ValueError
                    hours_offset = int(parts[0])
                    minutes_offset = int(parts[1])
                    offset = datetime.timedelta(hours=hours_offset, minutes=minutes_offset) * sign
                    tzinfo = datetime.timezone(offset)
                else:
                    raise ValueError
            except Exception as exc:
                raise ValueError(f"Unsupported tz format: {tz}") from exc

    return datetime.time(hour=hour, minute=minute, second=second,
                         microsecond=microseconds, tzinfo=tzinfo)

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Allow None to be dehydrated to None
    if value is None:
        return None

    # Basic type checks: must have hour attribute and not be a datetime
    if not hasattr(value, "hour"):
        raise TypeError(f"Expected a time object, got {type(value).__name__}")
    if hasattr(value, "year"):
        # datetime.datetime also has hour, so reject it
        raise TypeError(f"Expected a time object, got datetime.datetime")

    try:
        # Use isoformat to produce a serialisable string
        return value.isoformat()
    except Exception as exc:
        raise TypeError(f"Could not dehydrate time value: {value!r}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        # Try to extract x and y from a Point-like object
        if hasattr(value, 'x') and hasattr(value, 'y'):
            x = value.x
            y = value.y
        # Or from a tuple/list of two elements
        elif isinstance(value, (tuple, list)) and len(value) == 2:
            x, y = value
        else:
            raise ValueError("Unsupported type for point dehydration")
        # Ensure coordinates are numeric
        if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
            raise ValueError("Point coordinates must be numeric")
        return {'x': x, 'y': y}
    except Exception as e:
        raise ValueError(f"Error dehydrating point: {e}") from e

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Handle dataclass instances
        if hasattr(self, "__dataclass_fields__"):
            return list(self.__dataclass_fields__.keys())

        # Handle namedtuple instances
        if hasattr(self, "_fields"):
            return list(self._fields)

        # Handle a 'data' attribute that is dict-like
        if hasattr(self, "data"):
            data = getattr(self, "data")
            if isinstance(data, dict):
                return list(data.keys())
            if hasattr(data, "keys") and callable(data.keys):
                return list(data.keys())

        # Fallback to the instance's __dict__
        if hasattr(self, "__dict__"):
            return list(self.__dict__.keys())

        # If the instance itself is a dict (or dict subclass)
        if isinstance(self, dict):
            return list(self.keys())

        # If the instance has a keys method that is not this method
        if hasattr(self, "keys") and callable(self.keys):
            # Avoid recursion: check that the underlying function is not this method
            if getattr(self.keys, "__func__", None) is not keys:
                return list(self.keys())

        raise AttributeError("No keys available for this record")
    except Exception as exc:
        raise RuntimeError(f"Error retrieving keys: {exc}") from exc

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Validate the protocol_version argument
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    # Retrieve the mapping of protocol handlers from the class.
    # If the attribute does not exist, default to an empty dict.
    handlers = getattr(cls, "_protocol_handlers", {})

    # Ensure we have a dictionary; if not, attempt to convert.
    if not isinstance(handlers, dict):
        try:
            handlers = dict(handlers)
        except Exception:
            handlers = {}

    # If no specific protocol version requested, return a copy of all handlers.
    if protocol_version is None:
        return dict(handlers)

    # Return a dictionary containing the requested handler if it exists.
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    else:
        return {}

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Attempt to use a list-like index method if available
    try:
        return self._data.index(key)
    except AttributeError:
        # Fallback to manual search if _data is not list-like
        try:
            for idx, item in enumerate(self):
                if item == key:
                    return idx
        except TypeError:
            raise TypeError("object is not iterable")
        raise ValueError(f"{key} is not in list")
    except ValueError:
        # Propagate the original ValueError if key is not found
        raise

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to include only
    certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are
                 provided, all values will be included
    :return: list of values
    :rtype: list
    """
    try:
        # Determine if the object behaves like a mapping
        if not hasattr(self, "keys") or not hasattr(self, "values"):
            raise AttributeError("Object does not support mapping interface")

        # If no keys are provided, return all values
        if not keys:
            return list(self.values())

        # Prepare a list of all values for index-based access
        all_values = list(self.values())
        result = []

        for key in keys:
            # Skip None or other non-usable keys
            if key is None:
                continue

            # Handle integer indices (including negative indices)
            if isinstance(key, int):
                if -len(all_values) <= key < len(all_values):
                    result.append(all_values[key])
                # If index is out of range, ignore it
                continue

            # Handle non-integer keys (assumed to be hashable)
            try:
                if key in self:
                    result.append(self[key])
            except Exception:
                # If key lookup fails (e.g., unhashable), ignore it
                continue

        return result
    except Exception as exc:
        # Re-raise with a more informative message
        raise RuntimeError(f"Error retrieving values: {exc}") from exc

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError("mode must be 'READ' or 'WRITE'")

    # Validate bookmarks
    if bookmarks is not None:
        try:
            bookmarks_list = list(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable of bookmark values")
    else:
        bookmarks_list = None

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")

    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number (int or float)")

    # Validate db
    if db is not None and not isinstance(db, str):
        raise TypeError("db must be a string")

    # Validate imp_user
    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string")

    # Validate dehydration_hooks
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dictionary")
        for k, v in dehydration_hooks.items():
            if not isinstance(k, type):
                raise TypeError("dehydration_hooks keys must be types")
            if not callable(v):
                raise TypeError("dehydration_hooks values must be callable")

    # Validate hydration_hooks
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dictionary")
        for k, v in hydration_hooks.items():
            if not isinstance(k, type):
                raise TypeError("hydration_hooks keys must be types")
            if not callable(v):
                raise TypeError("hydration_hooks values must be callable")

    # Build the BEGIN message
    message = {"type": "BEGIN"}
    if mode is not None:
        message["mode"] = mode
    if bookmarks_list is not None:
        message["bookmarks"] = bookmarks_list
    if metadata is not None:
        message["metadata"] = metadata
    if timeout is not None:
        message["timeout"] = timeout
    if db is not None:
        message["db"] = db
    if imp_user is not None:
        message["imp_user"] = imp_user
    if dehydration_hooks is not None:
        message["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        message["hydration_hooks"] = hydration_hooks

    # Append to the output queue
    try:
        self._output_queue.append(message)
    except AttributeError:
        raise RuntimeError("Output queue not initialized or not writable")

    # Return a Response object (assumes Response is defined elsewhere)
    return Response(self, handlers)

def round_half_to_even(n):
    """
    Round a number to the nearest integer using the round-half-to-even rule.
    This is equivalent to Python's built-in round function but returns an int.
    """
    try:
        return int(round(n))
    except Exception as e:
        raise TypeError("Input must be a numeric value") from e

def deprecated(message):
    """Decorator for deprecating functions and methods.

    Usage:
        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        import warnings
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    # Validate parameters
    if not callable(timer):
        raise TypeError("timer must be a callable returning a numeric timestamp")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")
    if not isinstance(ttl, (int, float)):
        raise TypeError("ttl must be a number")
    if ttl <= 0:
        ttl = None  # No expiration
    if maxsize is not None:
        if not isinstance(maxsize, int):
            raise TypeError("maxsize must be an integer or None")
        if maxsize <= 0:
            maxsize = None  # Unlimited cache

    def decorating_function(user_function):
        cache = {}          # key -> (value, expire_time)
        order = []          # list of keys in LRU order (oldest first)

        def _make_key(args, kwargs):
            try:
                key = args
                if kwargs:
                    # Sort kwargs items to ensure consistent ordering
                    key += tuple(sorted(kwargs.items()))
                if typed:
                    # Include types of positional and keyword arguments
                    key += tuple(type(v) for v in args)
                    if kwargs:
                        key += tuple(type(v) for _, v in sorted(kwargs.items()))
                return key
            except TypeError:
                raise TypeError("unhashable type in arguments")

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            now = timer()
            # Check cache hit
            if key in cache:
                value, expire = cache[key]
                if expire is None or now < expire:
                    # Move key to end to mark as recently used
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    return value
                else:
                    # Expired entry
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
            # Cache miss or expired
            value = user_function(*args, **kwargs)
            expire_time = None if ttl is None else now + ttl
            cache[key] = (value, expire_time)
            order.append(key)
            # Evict if necessary
            if maxsize is not None and len(cache) > maxsize:
                oldest_key = order.pop(0)
                del cache[oldest_key]
            return value

        # Preserve function metadata
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__module__ = user_function.__module__
        wrapper.__annotations__ = user_function.__annotations__
        wrapper.__wrapped__ = user_function
        return wrapper

    return decorating_function

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        hits = 0
        misses = 0

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            # Build key
            try:
                key = args
                if kwargs:
                    # Sort kwargs items to ensure consistent ordering
                    key += tuple(sorted(kwargs.items()))
                if typed:
                    key += tuple(type(v) for v in args)
                    if kwargs:
                        key += tuple(type(v) for _, v in sorted(kwargs.items()))
            except TypeError:
                # Unhashable arguments; bypass cache
                return func(*args, **kwargs)

            if key in cache:
                # Move to end to mark as most recent
                cache.pop(key)
                cache[key] = cache[key]
                hits += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if maxsize > 0:
                    if len(cache) >= maxsize:
                        # Evict most recently used item (last inserted)
                        cache.popitem()
                cache[key] = result
                misses += 1
                return result

        def cache_info():
            return CacheInfo(hits, misses, maxsize, len(cache))

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = 0
            misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.__wrapped__ = func
        return wrapper

    return decorator

class CacheInfo:
    __slots__ = ("hits", "misses", "maxsize", "currsize")

    def __init__(self, hits, misses, maxsize, currsize):
        self.hits = hits
        self.misses = misses
        self.maxsize = maxsize
        self.currsize = currsize

    def __repr__(self):
        return (f"CacheInfo(hits={self.hits}, misses={self.misses}, "
                f"maxsize={self.maxsize}, currsize={self.currsize})")

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        return self[key]
    except KeyError:
        self[key] = default
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        if key in self:
            return self[key]
    except Exception:
        pass
    return default

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with limited stack depth and path truncation.
    """
    try:
        if e is None:
            return ''
        if not isinstance(e, BaseException):
            return str(e)

        tb = e.__traceback__
        if tb is None:
            return f"{type(e).__name__}: {e}"

        import traceback, os

        frames = traceback.extract_tb(tb)
        # Limit stack depth
        if isinstance(max_level, int) and max_level > 0:
            frames = frames[-max_level:]

        lines = []
        for frame in frames:
            filename = frame.filename
            # Truncate path if requested
            if isinstance(max_path_level, int) and max_path_level > 0:
                parts = filename.split(os.sep)
                if len(parts) > max_path_level:
                    parts = ['...'] + parts[-max_path_level:]
                filename = os.sep.join(parts)
            lines.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                lines.append(f'    {frame.line.strip()}')

        # Exception type and message
        exc_lines = traceback.format_exception_only(type(e), e)
        exc_text = ''.join(exc_lines).strip()

        if lines:
            return '\n'.join(lines + [exc_text])
        else:
            return exc_text
    except Exception as exc:
        # Fallback in case of unexpected errors during formatting
        return f"Error formatting exception: {exc}"

@staticmethod
    def file_to_textbuffer(file_name, encoding):
        """
        Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype str
        """
        # Validate input types
        if not isinstance(file_name, str) or not isinstance(encoding, str):
            return None
        try:
            with open(file_name, 'r', encoding=encoding) as f:
                return f.read()
        except Exception:
            return None

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    # Validate input
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        os = __import__('os')
        return os.path.isfile(file_name)
    except Exception:
        return False

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = getattr(self.__class__, "__name__", None)
    if not isinstance(name, str):
        return None
    for suffix in ("Py", "Fallback"):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """
    Return a mapping of attribute names to their descriptions as defined by the
    class interface.  By default, private attributes (those starting with an
    underscore) are omitted.  If ``all`` is True, private attributes are
    included.

    The description is taken from the attribute's ``__doc__`` if it exists,
    or from the ``fget`` docstring if the attribute is a property.  If no
    description is available, an empty string is used.

    Returns
    -------
    dict
        A dictionary mapping attribute names to description strings.
    """
    result = {}
    try:
        # Inspect class-level attributes
        for name, value in vars(self.__class__).items():
            if not all and name.startswith('_'):
                continue
            if callable(value):
                continue
            desc = ''
            try:
                if isinstance(value, property):
                    desc = getattr(value.fget, "__doc__", "") or ""
                else:
                    desc = getattr(value, "__doc__", "") or ""
            except Exception:
                desc = ""
            result[name] = desc.strip()
        # Optionally include instance attributes that are not methods
        for name, value in vars(self).items():
            if not all and name.startswith('_'):
                continue
            if callable(value):
                continue
            # Avoid duplicate keys from class attributes
            if name in result:
                continue
            desc = getattr(value, "__doc__", "") or ""
            result[name] = desc.strip()
    except Exception:
        # In case of unexpected errors, return an empty dict
        return {}
    return result

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    # Ensure output is a list
    if output is None:
        output = []
    elif not isinstance(output, list):
        raise TypeError(f"output must be a list, got {type(output).__name__}")

    # Helper to process a single item
    def _process(item):
        # Treat None as a no-op
        if item is None:
            return

        # Individual interfaces (strings, types, etc.) are appended directly
        if isinstance(item, (str, type)):
            output.append(item)
            return

        # Implements specs are tuples of length 2
        if isinstance(item, tuple):
            if len(item) == 2:
                output.append(item)
                return
            # Otherwise, expand the tuple
            for sub in item:
                _process(sub)
            return

        # Declarions: objects that expose 'interfaces' or 'args' attributes
        if hasattr(item, "interfaces"):
            _process(item.interfaces)
            return
        if hasattr(item, "args"):
            _process(item.args)
            return

        # Iterable containers (lists, sets, tuples, etc.) are expanded
        try:
            iterator = iter(item)
        except TypeError:
            # Not iterable, treat as a single interface
            output.append(item)
            return

        # Avoid treating strings as iterables of characters
        if isinstance(item, str):
            output.append(item)
            return

        for sub in iterator:
            _process(sub)

    # Main processing
    if sequence is None:
        return output

    # If sequence itself is a single interface, process it directly
    if isinstance(sequence, (str, type)):
        _process(sequence)
    else:
        try:
            iterator = iter(sequence)
        except TypeError:
            # Not iterable, treat as a single interface
            _process(sequence)
        else:
            for elem in iterator:
                _process(elem)

    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        return not bool(_c_optimizations_required())
    except NameError:
        # If the required function is not defined, assume optimizations are ignored
        return True
    except Exception:
        # Re-raise any other exception
        raise

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is defined and truthy, C optimizations are not required.
        # Otherwise, they are required.
        return not bool(globals().get("PURE_PYTHON", False))
    except Exception:
        # In case of any unexpected error (e.g., PURE_PYTHON not defined or not boolean),
        # assume C optimizations are required.
        return True

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context
        try:
            self.context = {}
        except AttributeError:
            # If the histogram does not have a context attribute, create one
            self.context = {}

        # Reinitialize bins
        try:
            # If an initial_value is defined and not None, use it to reset bins
            if hasattr(self, "initial_value") and self.initial_value is not None:
                # Preserve the current number of bins if they already exist
                if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                    bin_count = len(self.bins)
                    self.bins = [self.initial_value] * bin_count
                else:
                    # If bins are not yet defined, create a single bin with the initial value
                    self.bins = [self.initial_value]
            else:
                # Fall back to make_bins if available
                if hasattr(self, "make_bins") and callable(self.make_bins):
                    self.bins = self.make_bins()
                else:
                    # If no make_bins method, initialize an empty list of bins
                    self.bins = []
        except Exception as exc:
            # If any error occurs during reinitialization, raise a descriptive error
            raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError(f"separator must be a string, got {type(separator).__name__}")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError(f"header must be a string or None, got {type(header).__name__}")

    # Helper to determine if an object is iterable but not a string/bytes
    def _is_iterable(obj):
        if isinstance(obj, (str, bytes, bytearray)):
            return False
        try:
            iter(obj)
            return True
        except TypeError:
            return False

    # Attempt to obtain an iterable of points
    points_iter = None
    for attr in ("points", "data", "__iter__"):
        try:
            if attr == "__iter__":
                points_iter = iter(self)
            else:
                points_iter = iter(getattr(self, attr))
            break
        except (AttributeError, TypeError):
            continue
    if points_iter is None:
        raise AttributeError("Graph object has no iterable points attribute")

    lines = []

    for point in points_iter:
        if point is None:
            continue  # skip None points
        # Extract coordinate and value
        try:
            coord = point.coordinate
            val = point.value
        except AttributeError:
            try:
                coord, val = point
            except Exception:
                raise ValueError("Each point must provide coordinate and value "
                                 "or be a tuple of (coordinate, value)")

        # Convert coordinate to list of strings
        if _is_iterable(coord):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]

        # Convert value to list of strings
        if _is_iterable(val):
            val_parts = [str(v) for v in val]
        else:
            val_parts = [str(val)]

        line = separator.join(coord_parts + val_parts)
        lines.append(line)

    # Prepend header if provided
    if header is not None:
        lines.insert(0, header)

    # Join lines with newline; ensure trailing newline if header exists but no points
    if not lines:
        return "" if header is None else header + "\n"
    return "\n".join(lines) + ("\n" if header is not None else "") if header is not None else "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate the coordinate name
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Ensure the object has the expected attribute
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have an '_err_indices' attribute")
    err_dict = getattr(self, "_err_indices")
    if not isinstance(err_dict, dict):
        raise TypeError("The '_err_indices' attribute must be a dictionary")
    # Retrieve the indices for the given coordinate
    if coord_name not in err_dict:
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices")
    indices = err_dict[coord_name]
    # Normalize the result to a list
    if indices is None:
        return []
    if isinstance(indices, (list, tuple)):
        return list(indices)
    try:
        return list(indices)
    except TypeError:
        # Not iterable; return as a single-element list
        return [indices]

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    # Convert bins to numpy array
    try:
        bins_arr = np.asarray(bins)
    except Exception as exc:
        raise TypeError("bins must be array-like") from exc

    # Validate bins array
    if bins_arr.ndim == 0:
        raise ValueError("bins must be at least 1D")
    if not np.issubdtype(bins_arr.dtype, np.number):
        raise TypeError("bins array must contain numeric values")

    # Helper to validate a single edge array
    def _validate_edge_array(e_arr, dim):
        if e_arr.ndim != 1:
            raise ValueError(f"edge array at dimension {dim} must be 1D")
        if e_arr.size < 2:
            raise ValueError(f"edge array at dimension {dim} must have at least two elements")
        if not np.issubdtype(e_arr.dtype, np.number):
            raise TypeError(f"edge array at dimension {dim} must contain numeric values")
        widths = np.diff(e_arr)
        if np.any(widths <= 0):
            raise ValueError(f"edge array at dimension {dim} must be strictly increasing")
        return widths

    # Case 1: edges is a single array (1D histogram)
    if isinstance(edges, (list, tuple)):
        # List or tuple of edge arrays
        if len(edges) == 0:
            return 0.0
        edge_arrays = []
        widths_list = []
        for dim, e in enumerate(edges):
            try:
                e_arr = np.asarray(e)
            except Exception as exc:
                raise TypeError(f"edge at dimension {dim} must be array-like") from exc
            edge_arrays.append(e_arr)
            widths_list.append(_validate_edge_array(e_arr, dim))
        # Validate bins dimensionality
        if bins_arr.ndim != len(edge_arrays):
            raise ValueError("bins dimensionality does not match number of edge arrays")
        # Validate shape compatibility
        for dim, (e_arr, w) in enumerate(zip(edge_arrays, widths_list)):
            if bins_arr.shape[dim] != e_arr.size - 1:
                raise ValueError(f"bins shape mismatch for dimension {dim}")
        # Compute bin volumes via successive outer products
        vol = widths_list[0]
        for w in widths_list[1:]:
            vol = np.multiply.outer(vol, w)
        # Ensure volume shape matches bins shape
        if vol.shape != bins_arr.shape:
            raise ValueError("computed bin volume shape does not match bins shape")
        return float(np.sum(bins_arr * vol))
    else:
        # Single edge array
        try:
            edges_arr = np.asarray(edges)
        except Exception as exc:
            raise TypeError("edges must be array-like") from exc
        if edges_arr.ndim != 1:
            raise ValueError("edges must be a 1D array")
        if edges_arr.size < 2:
            return 0.0
        if bins_arr.ndim != 1:
            raise ValueError("bins must be 1D array for 1D edges")
        if bins_arr.size != edges_arr.size - 1:
            raise ValueError("bins size must be one less than edges size")
        widths = _validate_edge_array(edges_arr, 0)
        return float(np.sum(bins_arr * widths))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Handle None explicitly
        if seq is None:
            return False

        # If seq itself is a FillRequest instance, it's valid
        if isinstance(seq, FillRequest):
            return True

        # If seq is a Source instance, it's explicitly invalid
        if isinstance(seq, Source):
            return False

        # Strings and bytes are iterable but should not be treated as sequences here
        if isinstance(seq, (str, bytes)):
            return False

        # If seq is not iterable, it cannot be a sequence of FillRequests
        if not hasattr(seq, "__iter__"):
            return False

        # Iterate over the sequence to find at least one FillRequest
        for item in seq:
            if isinstance(item, FillRequest):
                return True

        # No FillRequest found in the sequence
        return False
    except Exception:
        # Any unexpected error results in a False verdict
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight = float(weight)
    except Exception:
        raise TypeError("weight must be a numeric value")
    # Validate histogram attributes
    if not hasattr(self, "edges"):
        raise AttributeError("Histogram has no 'edges' attribute")
    if not hasattr(self, "bins"):
        raise AttributeError("Histogram has no 'bins' attribute")
    # Convert coord to list
    if isinstance(coord, (str, bytes)):
        raise TypeError("coord must be an iterable of coordinates")
    if not hasattr(coord, "__iter__"):
        # single value
        if len(self.edges) != 1:
            raise ValueError("coord must be an iterable matching histogram dimensions")
        coord = [coord]
    else:
        coord = list(coord)
    if len(coord) != len(self.edges):
        raise ValueError("coord length must match histogram dimensions")
    # Find bin indices
    indices = []
    for dim, c in enumerate(coord):
        edges = self.edges[dim]
        if not hasattr(edges, "__iter__"):
            raise TypeError(f"edges for dimension {dim} must be iterable")
        # Check bounds
        if c < edges[0] or c >= edges[-1]:
            return  # ignore out-of-range coordinate
        # Find bin index
        idx = None
        for i in range(len(edges) - 1):
            if edges[i] <= c < edges[i + 1]:
                idx = i
                break
        if idx is None:
            return  # ignore if not found
        indices.append(idx)
    # Increment bin
    try:
        self.bins[tuple(indices)] += weight
    except Exception:
        # Fallback for nested list bins
        try:
            sub = self.bins
            for idx in indices[:-1]:
                sub = sub[idx]
            sub[indices[-1]] += weight
        except Exception as e:
            raise RuntimeError("Failed to increment histogram bin") from e

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    import re
    # Ensure the value is a string
    if not isinstance(value, str):
        raise ValidationError("Value must be a string.")
    # Retrieve the regex pattern from a global variable
    try:
        pattern = REGEX
    except NameError:
        raise ValidationError("No regex pattern defined.")
    if pattern is None:
        raise ValidationError("Regex pattern is None.")
    # Compile the pattern if it is a string
    if isinstance(pattern, str):
        try:
            regex = re.compile(pattern)
        except re.error as e:
            raise ValidationError(f"Invalid regex pattern: {e}")
    else:
        regex = pattern
    # Perform the full match
    try:
        if not regex.fullmatch(value):
            raise ValidationError(f"Value '{value}' does not match the pattern.")
    except Exception as e:
        raise ValidationError(f"Error during validation: {e}")

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` list from a partial
    Kubernetes response.

    Args:
        last_applied_manifest (list): The list to be updated.
        observer_schema (list): Schema describing the expected fields.
        response (list): Partial response from the Kubernetes API.

    Returns:
        None: The function updates ``last_applied_manifest`` in place.
    """
    # Basic validation
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            f"observer_schema must be a list, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, list):
        raise TypeError(
            f"response must be a list, got {type(response).__name__}"
        )

    # If the schema is empty, nothing to do
    if not observer_schema:
        return

    # Helper to update a dict element
    def _update_dict(target, schema, resp):
        if not isinstance(target, dict):
            # If target is not a dict, replace it with an empty dict
            target = {}
        if not isinstance(resp, dict):
            # If response is not a dict, nothing to update
            return target
        for field in schema:
            name = field.get("name")
            if not name:
                continue
            # Initialize if missing
            if name not in target:
                if name in resp:
                    target[name] = resp[name]
                else:
                    target[name] = None
            # Recurse into nested structures
            if "children" in field:
                child_schema = field["children"]
                if isinstance(target[name], dict):
                    target[name] = _update_dict(target[name], child_schema, resp.get(name, {}))
                elif isinstance(target[name], list):
                    # If the field is a list of dicts
                    target[name] = _update_list(target[name], child_schema, resp.get(name, []))
        return target

    # Helper to update a list element
    def _update_list(target, schema, resp):
        if not isinstance(target, list):
            target = []
        if not isinstance(resp, list):
            return target
        # Ensure target has enough elements
        for i, item_resp in enumerate(resp):
            if i >= len(target):
                # Append a new element based on schema
                if "children" in schema[0]:
                    target.append({})
                else:
                    target.append(None)
            # Update each element
            if "children" in schema[0]:
                child_schema = schema[0]["children"]
                target[i] = _update_dict(target[i], child_schema, item_resp)
            else:
                # Primitive list, just set the value
                target[i] = item_resp
        return target

    # Main update logic
    # If the observer_schema describes a list of dicts, we treat each item
    # accordingly. We assume the first schema element describes the list items.
    if observer_schema and "children" in observer_schema[0]:
        # List of dicts
        updated = _update_list(last_applied_manifest, observer_schema, response)
        # Update in place
        last_applied_manifest[:] = updated
    else:
        # List of primitives or mixed types
        # Simply replace with response if available
        if response:
            last_applied_manifest[:] = response
        else:
            # If response is empty, keep existing list
            pass
    return None

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
        TypeError: If the type of a field in the response does not match the
            expected type from the observer_schema.

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present. It also recurses into
    nested dictionaries and lists to ensure all missing subfields are populated.
    """
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for key, schema_val in observer_schema.items():
        # Ensure the key exists in the response
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in response")

        resp_val = response[key]

        # Handle nested dictionaries
        if isinstance(schema_val, dict):
            # Ensure the value in last_applied_manifest is a dict
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            elif not isinstance(last_applied_manifest[key], dict):
                raise TypeError(
                    f"Expected dict for field '{key}' in last_applied_manifest, "
                    f"got {type(last_applied_manifest[key]).__name__}"
                )
            if not isinstance(resp_val, dict):
                raise TypeError(
                    f"Expected dict for field '{key}' in response, "
                    f"got {type(resp_val).__name__}"
                )
            # Recurse into the nested dict
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema_val, resp_val
            )
            continue

        # Handle lists
        if isinstance(schema_val, list):
            # Ensure the value in last_applied_manifest is a list
            if key not in last_applied_manifest:
                last_applied_manifest[key] = []
            elif not isinstance(last_applied_manifest[key], list):
                raise TypeError(
                    f"Expected list for field '{key}' in last_applied_manifest, "
                    f"got {type(last_applied_manifest[key]).__name__}"
                )
            if not isinstance(resp_val, list):
                raise TypeError(
                    f"Expected list for field '{key}' in response, "
                    f"got {type(resp_val).__name__}"
                )
            # Delegate list handling to the list-specific updater
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[key], schema_val, resp_val
            )
            continue

        # Primitive values: set only if missing
        if key not in last_applied_manifest:
            last_applied_manifest[key] = resp_val
        # If the key already exists, we leave it unchanged (no overwrite)
        # This preserves any previously set values that may not be present in the response
        # but are still part of the last applied manifest.

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its observer schema. Existing custom
        schemas are preserved.
    """
    # Default schema to apply when no custom schema is defined
    DEFAULT_SCHEMA = {"metadata": {"name": True, "namespace": True}, "status": True}

    try:
        # Safely access the application spec and manifest
        spec = getattr(app, "spec", None)
        if spec is None:
            return {}

        manifest = getattr(spec, "manifest", None)
        if not isinstance(manifest, list):
            return {}

        # Existing observer schema mapping (kind -> schema)
        observer_schema = getattr(spec, "observer_schema", {})
        if not isinstance(observer_schema, dict):
            observer_schema = {}

        # Iterate over each resource in the manifest
        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue
            # If no custom schema for this kind, set the default
            if kind not in observer_schema:
                observer_schema[kind] = DEFAULT_SCHEMA

        return observer_schema

    except Exception:
        # In case of unexpected errors, return an empty mapping
        return {}

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        log = getattr(self, 'validation_log', [])
        if not hasattr(log, '__iter__'):
            raise TypeError("validation_log is not iterable")
        lines = []
        for entry in log:
            try:
                lines.append(f"{prefix}{entry}")
            except Exception:
                lines.append(f"{prefix}{str(entry)}")
        return "\n".join(lines)
    except Exception:
        return ""

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")

    # Determine the specification version
    allowed_versions = {"1.0", "2.0"}
    spec_version = getattr(self, "spec_version", None)

    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Expect format like "inventory:1.0" or "inventory:2.0"
            parts = type_val.split(":")
            if len(parts) == 2 and parts[1] in allowed_versions:
                spec_version = parts[1]

    if spec_version not in allowed_versions:
        raise ValueError(f"Unsupported or missing specification version: {spec_version}")

    # Store the resolved spec_version back on the instance for future use
    self.spec_version = spec_version

    # Basic required keys
    required_keys = ["name", "items"]
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key: {key}")

    if not isinstance(inventory["name"], str):
        raise ValueError("Inventory 'name' must be a string.")

    if not isinstance(inventory["items"], list):
        raise ValueError("Inventory 'items' must be a list.")

    # Validate each item according to the spec version
    for idx, item in enumerate(inventory["items"]):
        if not isinstance(item, dict):
            raise ValueError(f"Item at index {idx} must be a dictionary.")
        if "id" not in item or "value" not in item:
            raise ValueError(f"Item at index {idx} missing required 'id' or 'value' fields.")
        if not isinstance(item["id"], (int, str)):
            raise ValueError(f"Item 'id' at index {idx} must be an int or str.")
        if not isinstance(item["value"], (int, float, str)):
            raise ValueError(f"Item 'value' at index {idx} must be int, float, or str.")

        if spec_version == "2.0":
            if "metadata" not in item:
                raise ValueError(f"Item at index {idx} missing 'metadata' for spec 2.0.")
            if not isinstance(item["metadata"], dict):
                raise ValueError(f"Item 'metadata' at index {idx} must be a dictionary.")

    # All checks passed
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type and identity checks
    if prior is None:
        raise ValueError("prior cannot be None")
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same InventoryValidator class")
    if prior is self:
        raise ValueError("prior cannot be the same instance as the current inventory")

    # Ensure required attributes exist
    for attr in ("version", "items"):
        if not hasattr(self, attr):
            raise AttributeError(f"Current inventory is missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"Prior inventory is missing required attribute '{attr}'")

    # Version comparison
    try:
        if prior.version >= self.version:
            raise ValueError(
                f"Prior inventory version ({prior.version}) must be less than current version ({self.version})"
            )
    except Exception as exc:
        raise TypeError("Inventory 'version' attribute must be comparable (e.g., int, float, or str)") from exc

    # Items comparison
    # Expect items to be a mapping (dict-like) of item identifiers to quantities
    if not isinstance(self.items, dict) or not isinstance(prior.items, dict):
        raise TypeError("Inventory 'items' attribute must be a dictionary mapping item IDs to quantities")

    for item_id, prior_qty in prior.items.items():
        if item_id not in self.items:
            raise ValueError(f"Item '{item_id}' present in prior inventory is missing from current inventory")
        current_qty = self.items[item_id]
        if current_qty < prior_qty:
            raise ValueError(
                f"Quantity of item '{item_id}' in current inventory ({current_qty}) "
                f"is less than quantity in prior inventory ({prior_qty})"
            )

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to iterate over all entries in the inventory
    def _iter_entries(inv):
        if isinstance(inv, dict):
            # If dict contains a list of entries under a common key
            for key, value in inv.items():
                if isinstance(value, list):
                    for entry in value:
                        yield entry
                elif isinstance(value, dict):
                    # nested dict, try to find list inside
                    for sub in _iter_entries(value):
                        yield sub
        elif isinstance(inv, list):
            for entry in inv:
                yield entry
        else:
            # Unsupported type, nothing to iterate
            return

    result = {}
    # Normalize version to comparable type
    try:
        target_version = int(version)
    except Exception:
        target_version = version

    for entry in _iter_entries(inventory):
        if not isinstance(entry, dict):
            continue
        # Extract fields with defaults
        logical_path = entry.get("logical_path") or entry.get("logicalPath") or entry.get("path")
        content_file = entry.get("content_file") or entry.get("contentFile") or entry.get("file")
        entry_version = entry.get("version")
        duplicate_of = entry.get("duplicate_of") or entry.get("duplicateOf")

        # Skip if essential fields missing
        if logical_path is None or content_file is None:
            continue

        # Determine if this entry should be included
        include = False
        # If entry version matches target version
        if entry_version is not None:
            try:
                ev = int(entry_version)
            except Exception:
                ev = entry_version
            if ev == target_version:
                include = True
        # If entry is a duplicate of a version <= target_version
        if not include and duplicate_of is not None:
            try:
                dv = int(duplicate_of)
            except Exception:
                dv = duplicate_of
            if dv <= target_version:
                include = True

        if include:
            result.setdefault(logical_path, set()).add(content_file)

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic input validation
    if fixity is None:
        raise TypeError("fixity must not be None")
    if not isinstance(fixity, dict):
        raise TypeError(f"fixity must be a dict, got {type(fixity).__name__}")

    if manifest_files is None:
        raise TypeError("manifest_files must not be None")
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise TypeError("manifest_files must be an iterable of file paths")

    for path in manifest_set:
        if not isinstance(path, str):
            raise TypeError(f"manifest file path must be a string, got {type(path).__name__}")

    # Validate the fixity block structure
    if 'files' not in fixity:
        raise ValueError("fixity block missing required 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise TypeError(f"fixity['files'] must be a list, got {type(files).__name__}")

    seen_paths = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise TypeError(f"fixity file entry at index {idx} must be a dict, got {type(entry).__name__}")

        # Required keys
        for key in ('path', 'hash', 'size'):
            if key not in entry:
                raise ValueError(f"fixity file entry at index {idx} missing required key '{key}'")

        path = entry['path']
        if not isinstance(path, str):
            raise TypeError(f"fixity file entry at index {idx} 'path' must be a string, got {type(path).__name__}")
        if not path:
            raise ValueError(f"fixity file entry at index {idx} 'path' cannot be empty")
        if path in seen_paths:
            raise ValueError(f"duplicate file path '{path}' in fixity block")
        seen_paths.add(path)

        if path not in manifest_set:
            raise ValueError(f"fixity references file '{path}' not present in manifest")

        h = entry['hash']
        if not isinstance(h, str):
            raise TypeError(f"fixity file entry at index {idx} 'hash' must be a string, got {type(h).__name__}")
        if not h:
            raise ValueError(f"fixity file entry at index {idx} 'hash' cannot be empty")

        sz = entry['size']
        if not isinstance(sz, int):
            raise TypeError(f"fixity file entry at index {idx} 'size' must be an int, got {type(sz).__name__}")
        if sz < 0:
            raise ValueError(f"fixity file entry at index {idx} 'size' must be non-negative")

    # If all checks pass, return True
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        if not os.path.isdir(path):
            return []
        entries = os.listdir(path)
        files = []
        for entry in entries:
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                files.append(entry)
        return files
    except (OSError, TypeError):
        return []

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Path to the source directory or zipfile (unused in this function but kept for compatibility).
    xmls : list or str
        List of XML filenames or a single XML filename.
    files : list
        List of files in the folder or zipfile.

    Returns
    -------
    dict
        key: name of the XML files (basename without extension)
        value: list of files that share the same basename
    """
    import os

    # Validate inputs
    if not isinstance(files, list):
        raise TypeError(f"'files' must be a list, got {type(files).__name__}")
    if xmls is None:
        return {}
    if isinstance(xmls, str):
        xmls = [xmls]
    if not isinstance(xmls, list):
        raise TypeError(f"'xmls' must be a list or str, got {type(xmls).__name__}")

    # Prepare mapping from xml basename to list of matching files
    grouped = {}
    # Build a set of xml basenames for quick lookup
    xml_basenames = {}
    for xml in xmls:
        if not isinstance(xml, str):
            continue
        base, _ = os.path.splitext(os.path.basename(xml))
        xml_basenames[base] = xml  # map base to full xml name if needed

    # Initialize groups with empty lists
    for base in xml_basenames:
        grouped[base] = []

    # Iterate over files and group them
    for f in files:
        if not isinstance(f, str):
            continue
        file_base, _ = os.path.splitext(os.path.basename(f))
        if file_base in xml_basenames:
            grouped[file_base].append(f)

    # Optionally, remove empty groups if desired
    # grouped = {k: v for k, v in grouped.items() if v}

    return grouped

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate language code
    if not isinstance(lang, str):
        raise TypeError("lang must be a string")
