    # Add or update the rendition
    self.renditions[lang] = file_path

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to a dictionary of file paths and their binary contents.
    """
    import zipfile
    import os

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First pass: identify XML basenames
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = os.path.basename(info.filename)
                base, ext = os.path.splitext(name)
                if ext.lower() == '.xml':
                    xml_basenames.add(base)

            # Second pass: group files by basename
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = os.path.basename(info.filename)
                base, _ = os.path.splitext(name)
                if base in xml_basenames:
                    if base not in result:
                        result[base] = {}
                    try:
                        data = zf.read(info)
                    except Exception:
                        # Skip files that cannot be read
                        continue
                    result[base][info.filename] = data
    except FileNotFoundError:
        raise ValueError(f"Zip file not found: {zip_path}")
    except zipfile.BadZipFile:
        raise ValueError(f"Bad zip file: {zip_path}")
    except Exception as e:
        raise ValueError(f"Error processing zip file {zip_path}: {e}")

    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None or not hasattr(node, "xpath"):
        return None
    if not isinstance(pubdate_xpaths, (list, tuple)):
        return None
    if not pubdate_xpaths:
        return None

    for xpath_expr in pubdate_xpaths:
        try:
            result = node.xpath(xpath_expr)
            if result:
                first = result[0]
                # If the result is an element, return its text content
                if hasattr(first, "text"):
                    text = first.text
                    return text.strip() if text else None
                # If the result is a string or other type, convert to string
                return str(first).strip()
        except Exception:
            # Ignore any errors and continue with the next xpath
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Ensure indent is a non‑negative integer
    try:
        indent = int(indent)
        if indent < 0:
            indent = 0
    except Exception:
        indent = 0

    # Ensure debug is a boolean
    debug = bool(debug)

    # Try to use a custom pretty method if available
    try:
        if hasattr(self, "to_pretty") and callable(self.to_pretty):
            return self.to_pretty(indent=indent, debug=debug)
    except Exception:
        pass

    # Build a representation
    try:
        if hasattr(self, "__dict__"):
            attrs = {}
            for key, value in self.__dict__.items():
                try:
                    if hasattr(value, "pretty") and callable(value.pretty):
                        attrs[key] = value.pretty(indent=indent + 2, debug=debug)
                    else:
                        attrs[key] = repr(value)
                except Exception:
                    attrs[key] = f"<error retrieving attribute {key}>"
            body = ", ".join(f"{k}={attrs[k]}" for k in sorted(attrs))
            rep = f"{self.__class__.__name__}({body})"
        else:
            rep = repr(self)
    except Exception as e:
        rep = f"<error pretty printing {self}: {e}>"

    # Apply indentation
    if indent:
        prefix = " " * indent
        rep = "\n".join(prefix + line for line in rep.splitlines())

    # Append debug information if requested
    if debug:
        rep += f"\nDebug: type={type(self).__name__}, id={id(self)}"

    return rep

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def _apply_absorption(expr):
        try:
            # Helper to check membership in args
            def contains(arg, seq):
                return any(arg == x for x in seq)

            # Absorption for And
            if getattr(expr, "is_And", False):
                # Standard absorption: A & (A | B) = A
                for a in getattr(expr, "args", ()):
                    for sub in getattr(expr, "args", ()):
                        if getattr(sub, "is_Or", False):
                            if contains(a, getattr(sub, "args", ())):
                                # Find B
                                B = [x for x in getattr(sub, "args", ()) if x != a]
                                if len(B) == 1:
                                    return a
                # Negative absorption: A & (~A | B) = A & B
                for a in getattr(expr, "args", ()):
                    for sub in getattr(expr, "args", ()):
                        if getattr(sub, "is_Or", False):
                            # Look for Not(a) inside sub
                            for x in getattr(sub, "args", ()):
                                if getattr(x, "is_Not", False) and getattr(x, "args", ()):
                                    if x.args[0] == a:
                                        B = [y for y in getattr(sub, "args", ()) if not (getattr(y, "is_Not", False) and getattr(y, "args", ()) and y.args[0] == a)]
                                        if len(B) == 1:
                                            # Construct A & B
                                            return expr.func(a, B[0])
            # Absorption for Or
            if getattr(expr, "is_Or", False):
                # Standard absorption: A | (A & B) = A
                for a in getattr(expr, "args", ()):
                    for sub in getattr(expr, "args", ()):
                        if getattr(sub, "is_And", False):
                            if contains(a, getattr(sub, "args", ())):
                                B = [x for x in getattr(sub, "args", ()) if x != a]
                                if len(B) == 1:
                                    return a
                # Negative absorption: A | (~A & B) = A | B
                for a in getattr(expr, "args", ()):
                    for sub in getattr(expr, "args", ()):
                        if getattr(sub, "is_And", False):
                            for x in getattr(sub, "args", ()):
                                if getattr(x, "is_Not", False) and getattr(x, "args", ()):
                                    if x.args[0] == a:
                                        B = [y for y in getattr(sub, "args", ()) if not (getattr(y, "is_Not", False) and getattr(y, "args", ()) and y.args[0] == a)]
                                        if len(B) == 1:
                                            return expr.func(a, B[0])
        except Exception:
            # If any unexpected structure, just return the original expression
            pass
        return expr

    # Validate input
    if args is None:
        return []
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of expressions")

    result = []
    for expr in iterator:
        # If expr is not an expression object, keep as is
        if expr is None:
            result.append(expr)
            continue
        try:
            simplified = _apply_absorption(expr)
            result.append(simplified)
        except Exception:
            # In case of any error, keep the original expression
            result.append(expr)
    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate hook
    if hook is None:
        raise ValueError("Hook cannot be None")
    # Ensure the registry exists and is a dictionary
    if not hasattr(self, "_registry") or not isinstance(self._registry, dict):
        self._registry = {}
    # Ensure a list exists for this hook
    if hook not in self._registry:
        self._registry[hook] = []
    def decorator(func):
        if not callable(func):
            raise TypeError(f"Handler for hook {hook!r} must be callable")
        # Avoid duplicate registration
        if func not in self._registry[hook]:
            self._registry[hook].append(func)
        return func
    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    def wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception:
            # Propagate any exception from the original function
            raise
        if sys.version_info[0] < 3:
            # In Python 2, ensure the result is a bytestring
            if isinstance(result, unicode):
                try:
                    return result.encode('utf-8')
                except Exception:
                    # If encoding fails, return the original result
                    return result
            else:
                return result
        else:
            # In Python 3, return the result unchanged
            return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to import importlib.metadata (Python 3.8+)
    try:
        import importlib.metadata as importlib_metadata
    except Exception:
        importlib_metadata = None

    # Determine a plausible package name from the current module context
    pkg_name = None
    if __package__:
        pkg_name = __package__
    else:
        # Fallback to the top-level module name
        pkg_name = __name__.split('.')[0]
    if pkg_name in ('__main__', ''):
        pkg_name = None

    # 1. Try importlib.metadata
    if pkg_name and importlib_metadata:
        try:
            version = importlib_metadata.version(pkg_name)
            return {"version": version}
        except Exception:
            pass

    # 2. Try pkg_resources (setuptools)
    try:
        import pkg_resources
        if pkg_name:
            try:
                version = pkg_resources.get_distribution(pkg_name).version
                return {"version": version}
            except Exception:
                pass
    except Exception:
        pass

    # 3. Try to get a git description
    try:
        import subprocess
        git_desc = subprocess.run(
            ["git", "describe", "--tags", "--always", "--dirty"],
            capture_output=True,
            text=True,
            check=True,
        ).stdout.strip()
        if git_desc:
            return {"version": git_desc}
    except Exception:
        pass

    # 4. Fallback to a default version
    return {"version": "0.0.0"}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate pieces
    if pieces is None:
        raise TypeError("pieces cannot be None")
    if isinstance(pieces, str):
        pieces = [pieces]
    elif not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple of version components")
    # Convert pieces to strings, filter out None or empty after strip
    cleaned = []
    for p in pieces:
        if p is None:
            continue
        try:
            s = str(p).strip()
        except Exception:
            s = ''
        if s:
            cleaned.append(s)
    # Validate style
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()
    if style == 'none':
        return ''
    if style in ('semver', 'pep440', 'dot', 'full'):
        sep = '.'
    elif style == 'dash':
        sep = '-'
    elif style == 'underscore':
        sep = '_'
    elif style == 'short':
        # drop trailing numeric zeros
        i = len(cleaned) - 1
        while i >= 0:
            comp = cleaned[i]
            if comp.isdigit() and int(comp) == 0:
                i -= 1
            else:
                break
        cleaned = cleaned[:i+1]
        sep = '.'
    else:
        raise ValueError(f"Unsupported style: {style}")
    return sep.join(cleaned)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # If pieces is a string, check for '+' directly
        if isinstance(pieces, str):
            has_plus = '+' in pieces
        else:
            # Assume iterable; check each element
            has_plus = any(item == '+' for item in pieces)
    except Exception:
        # If pieces is not iterable or any error occurs, treat as no plus
        has_plus = False
    return '.' if has_plus else '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Normalize commands to a list
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, list):
        raise TypeError("commands must be a string or a list of strings")

    # Normalize args to a list
    if args is None:
        args = []
    if not isinstance(args, list):
        raise TypeError("args must be a list of strings")

    # Validate env
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Merge environment variables
    merged_env = os.environ.copy()
    if env:
        merged_env.update(env)

    # Collect output from all commands
    outputs = []

    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")

        full_cmd = [cmd] + args

        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")

        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=merged_env,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
                text=True,
                check=True
            )
            outputs.append(result.stdout)
        except subprocess.CalledProcessError as e:
            err_msg = e.stderr if e.stderr else ""
            raise RuntimeError(
                f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}. "
                f"Error: {err_msg}"
            ) from e

    return "".join(outputs)

def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    # Attempt to import the real VersioneerConfig if available.
    try:
        from versioneer import VersioneerConfig
    except Exception:
        # Fallback simple placeholder class if the real one is not available.
        class VersioneerConfig:
            pass

    # Instantiate the configuration object.
    config = VersioneerConfig()

    # Populate with common default values used by Versioneer.
    # These values are typical for a git-based project using PEP 440 style.
    try:
        config.VCS = "git"
    except Exception:
        pass
    try:
