    except Exception:
        pass
    try:
        config.versionfile_source = "src/package/_version.py"
    except Exception:
        pass
    try:
        config.versionfile_build = "build/package/_version.py"
    except Exception:
        pass
    try:
        config.tag_prefix = ""
    except Exception:
        pass
    try:
        config.parentdir_prefix_version = ""
    except Exception:
        pass
    try:
        config.search_parent_directories = True
    except Exception:
        pass
    try:
        config.verbose = False
    except Exception:
        pass

    return config

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS."""
    # Support usage as @register_vcs_handler('git') or @register_vcs_handler('git', func)
    if method is None:
        def decorator(func):
            return register_vcs_handler(vcs, func)
        return decorator

    # Validate inputs
    if not isinstance(vcs, str):
        raise TypeError(f"vcs must be a string, got {type(vcs).__name__}")
    if not callable(method):
        raise TypeError(f"method must be callable, got {type(method).__name__}")

    # Initialize registry on the decorator function if not present
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}

    # Register the handler, overriding any existing handler for the same VCS
    register_vcs_handler._registry[vcs] = method

    # Attach metadata to the method for introspection
    setattr(method, "_vcs_handler", vcs)

    return method

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Validate that the instance has a root_path attribute
    if not hasattr(self, 'root_path'):
        raise AttributeError("Instance must have a 'root_path' attribute.")
    root_path = self.root_path
    if not isinstance(root_path, str) or not root_path:
        raise ValueError("root_path must be a non-empty string.")
    import os
    import json
    # Check if the path already exists
    if os.path.exists(root_path):
        if os.path.isdir(root_path):
            raise FileExistsError(f"Root path '{root_path}' already exists.")
        else:
            raise ValueError(f"Root path '{root_path}' exists and is not a directory.")
    # Create the root directory
    try:
        os.makedirs(root_path, exist_ok=False)
    except OSError as e:
        raise OSError(f"Failed to create root directory '{root_path}': {e}") from e
    # Create the .ocfl_root file with minimal metadata
    ocfl_root_path = os.path.join(root_path, '.ocfl_root')
    ocfl_data = {
        "ocfl_version": "1.0",
        "layout": "simple",
        "layout_version": "1.0"
    }
    try:
        with open(ocfl_root_path, 'w', encoding='utf-8') as f:
            json.dump(ocfl_data, f, indent=2)
    except OSError as e:
        raise OSError(f"Failed to write .ocfl_root file at '{ocfl_root_path}': {e}") from e
    return None

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise ValueError("version_dirs must be a list or tuple of directory names")
    if not hasattr(self, "inventory_dir"):
        raise AttributeError("self.inventory_dir is required for locating inventories")
    if not hasattr(self, "root_inventory"):
        raise AttributeError("self.root_inventory is required for digest comparison")
    root_inv = self.root_inventory
    if not isinstance(root_inv, dict):
        raise TypeError("self.root_inventory must be a dictionary mapping file paths to digests")

    # Dynamically import required modules without using explicit import statements
    json_mod = __import__("json")
    os_mod = __import__("os")

    # Store differences: file_path -> list of version directories where digest differs
    differences = {}

    for vdir in version_dirs:
        # Build path to the inventory file for this version
        inv_path = os_mod.path.join(self.inventory_dir, vdir, "inventory.json")
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json_mod.load(f)
        except FileNotFoundError:
            raise FileNotFoundError(f"Missing inventory file for version directory '{vdir}' at '{inv_path}'")
        except json_mod.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in inventory for '{vdir}': {e}")
        except Exception as e:
            raise RuntimeError(f"Error reading inventory for '{vdir}': {e}")

        if not isinstance(inv, dict):
            raise TypeError(f"Inventory for '{vdir}' must be a dictionary of file digests")

        # Ensure the inventory contains all files that should exist up to this point
        # (i.e., all keys in the root inventory that are present in this version)
        # If the inventory contains unexpected files, we simply ignore them for digest comparison.
        for file_path, digest in inv.items():
            root_digest = root_inv.get(file_path)
            if root_digest is None:
                # File not present in root inventory; skip comparison
                continue
            if digest != root_digest:
                differences.setdefault(file_path, []).append(vdir)

    # Store the differences on the instance for later validation
    self.different_digests = differences
    return differences

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import json
    import fnmatch

    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            # Find a file that matches the Namaste pattern "0=*"
            namaste_file = None
            for entry in os.listdir(path):
                if fnmatch.fnmatch(entry, "0=*"):
                    namaste_file = entry
                    break
            if not namaste_file:
                return "No Namaste file found in directory"
            namaste_path = os.path.join(path, namaste_file)
            try:
                with open(namaste_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
            except json.JSONDecodeError:
                return "Namaste file is not valid JSON"
            except OSError as e:
                return f"Error reading Namaste file: {e}"
            # Determine type based on JSON content
            if isinstance(data, dict):
                if "ocfl_object_id" in data:
                    return "object"
                if "ocfl_version" in data:
                    return "root"
                return "Namaste file missing required fields"
            else:
                return "Namaste file does not contain a JSON object"
        return f"Unknown path type: {path}"
    except OSError as e:
        return f"Error accessing path: {e}"
    except Exception as e:
        return f"Unexpected error: {e}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dict; if None, start with an empty dict
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # If no bug_ids provided, nothing to amend
    if bug_ids is None:
        return params

    # Accept a single string id as a list of one element
    if isinstance(bug_ids, str):
        bug_ids = [bug_ids]

    # Ensure bug_ids is an iterable of ids
    if not isinstance(bug_ids, (list, tuple, set)):
        raise TypeError("bug_ids must be an iterable of ids")

    # Clean and convert all ids to strings, filtering out empty/None values
    cleaned_bug_ids = [str(bid).strip() for bid in bug_ids if bid is not None and str(bid).strip() != ""]
    if not cleaned_bug_ids:
        return params

    # Extract any existing ids from params
    existing_ids = []
    if "ids" in params:
        existing = params["ids"]
        if isinstance(existing, str):
            existing_ids = [s.strip() for s in existing.split(",") if s.strip()]
        elif isinstance(existing, (list, tuple, set)):
            existing_ids = [str(e).strip() for e in existing if e is not None and str(e).strip() != ""]
        # If existing is of an unexpected type, ignore it

    # Combine existing and new ids, preserving order and removing duplicates
    combined_ids = []
    seen = set()
    for id_ in existing_ids + cleaned_bug_ids:
        if id_ not in seen:
            seen.add(id_)
            combined_ids.append(id_)

    # Update the params dictionary
    params["ids"] = ",".join(combined_ids)
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping_node(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    def merge_mapping_nodes(map1, map2):
        # Merge two MappingNode objects by combining their value lists
        # and recursively merging duplicates.
        if not (is_mapping_node(map1) and is_mapping_node(map2)):
            return map2
        combined = list(map1.value) + list(map2.value)
        merged_list = deep_merge_nodes(combined)
        # Construct a new MappingNode with the same tag as map1
        return type(map1)(map1.tag, merged_list)

    if not isinstance(nodes, list):
        raise ValueError('nodes must be a list')
    merged = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each item must be a tuple of (key_node, value_node)')
        key_node, value_node = item
        if not hasattr(key_node, 'value'):
            raise ValueError('key_node must have a value attribute')
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = merged[key]
            if is_mapping_node(existing_value_node) and is_mapping_node(value_node):
                merged_value = merge_mapping_nodes(existing_value_node, value_node)
                merged[key] = (existing_key_node, merged_value)
            else:
                # Non-mapping nodes: last wins, keep original key node
                merged[key] = (existing_key_node, value_node)
    return list(merged.values())

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    try:
        import argparse
    except ImportError as exc:
        raise ImportError("argparse module is required") from exc

    if parser is None:
        raise TypeError("parser cannot be None")
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    try:
        actions = parser._actions
    except AttributeError as exc:
        raise AttributeError("parser does not have _actions attribute") from exc

    flags = []
    for action in actions:
        # action.option_strings is a list of flag strings (e.g., ['-h', '--help'])
        if hasattr(action, "option_strings"):
            flags.extend(action.option_strings)
    return " ".join(flags)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping_node(node):
        try:
            return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'
        except Exception:
            return False

    def merge_mapping_nodes(node1, node2):
        """
        Merge node2 into node1. Both are mapping nodes.
        """
        try:
            # Build index map for node1's value list
            index_map = {}
            for idx, pair in enumerate(node1.value):
                key_node = pair[0]
                key_val = getattr(key_node, 'value', None)
                if key_val is not None:
                    index_map[key_val] = idx

            for pair in node2.value:
                key_node, val_node = pair
                key_val = getattr(key_node, 'value', None)
                if key_val is None:
                    continue
                if key_val in index_map:
                    idx = index_map[key_val]
                    existing_val_node = node1.value[idx][1]
                    if is_mapping_node(existing_val_node) and is_mapping_node(val_node):
                        # Recursively merge
                        merge_mapping_nodes(existing_val_node, val_node)
                    else:
                        # Replace with new value
                        node1.value[idx] = (key_node, val_node)
                else:
                    # Append new pair
                    node1.value.append((key_node, val_node))
                    index_map[key_val] = len(node1.value) - 1
        except Exception:
            # In case of unexpected structure, fall back to replacing node1 with node2
            return node2
        return node1

    result = []
    seen = {}
    for key_node, val_node in nodes:
        try:
            key_val = getattr(key_node, 'value', None)
        except Exception:
            key_val = None
        if key_val is None:
            # Skip invalid key
            continue
        if key_val not in seen:
            seen[key_val] = len(result)
            result.append((key_node, val_node))
        else:
            idx = seen[key_val]
            existing_key_node, existing_val_node = result[idx]
            if is_mapping_node(existing_val_node) and is_mapping_node(val_node):
                merged_node = merge_mapping_nodes(existing_val_node, val_node)
                result[idx] = (existing_key_node, merged_node)
            else:
                # Last wins
                result[idx] = (existing_key_node, val_node)
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    if parser is None:
        raise ValueError("parser cannot be None")
    # Basic check for an ArgumentParser-like object
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    try:
        for action in parser._actions:
            # Some actions may not have option_strings (e.g., positional arguments)
            option_strings = getattr(action, "option_strings", [])
            for opt in option_strings:
                if opt:  # ignore empty strings
                    flags.append(opt)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc
    return " ".join(flags)

def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    try:
        import argparse
        from borgmatic.cli.main import get_parser

        parser = get_parser()
        commands = []
        options = []

        def gather(p):
            for action in p._actions:
                if isinstance(action, argparse._SubParsersAction):
                    for name, subparser in action.choices.items():
                        commands.append(name)
                        gather(subparser)
                else:
                    if action.option_strings:
                        options.extend(action.option_strings)

        gather(parser)

        all_words = commands + options
        words_str = " ".join(all_words)

        script = f'''
_borgmatic_completion()
{{
    local cur prev words cword
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    COMPREPLY=( $(compgen -W "{words_str}" -- "$cur") )
}}
complete -F _borgmatic_completion borgmatic
'''
        return script
    except Exception:
        # Fallback: use borgmatic --help to extract commands and options
        script = '''
_borgmatic_completion()
{{
    local cur prev words cword
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    COMPREPLY=( $(compgen -W "$(borgmatic --help | awk '/^  -/ {print $1} /^  --/ {print $1} /^  [a-z]/ {print $1}')" -- "$cur") )
}}
complete -F _borgmatic_completion borgmatic
'''
        return script

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    # Validate input: all elements must be strings
    if any(not isinstance(arg, str) for arg in unparsed_arguments):
        raise TypeError("All arguments must be strings")

    args = list(unparsed_arguments)

    # If no arguments, return an empty global namespace
    if not args:
        return {"global": argparse.Namespace()}

    # Find the first non-option argument to treat as subparser name
    subparser_name = None
    subparser_start_index = None
    for i, arg in enumerate(args):
        if not arg.startswith('-'):
            subparser_name = arg
            subparser_start_index = i
            break

    # Parse global arguments (everything before the subparser, if any)
    global_parser = argparse.ArgumentParser(add_help=False)
    try:
        global_namespace, global_unknown = global_parser.parse_known_args(
            args[:subparser_start_index] if subparser_start_index is not None else args
        )
    except Exception as exc:
        raise ValueError(f"Error parsing global arguments: {exc}") from exc

    result = {"global": global_namespace}

    # If a subparser was found, parse its arguments
    if subparser_name is not None:
        subparser_parser = argparse.ArgumentParser(add_help=False)
        try:
            sub_namespace, sub_unknown = subparser_parser.parse_known_args(
                args[subparser_start_index + 1 :]
            )
        except Exception as exc:
            raise ValueError(f"Error parsing subparser '{subparser_name}' arguments: {exc}") from exc

        # Attach unknown arguments for debugging or further processing
        sub_namespace.unknown = sub_unknown
        result[subparser_name] = sub_namespace

    return result

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator that yields slices of the response list
    def _generator():
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]

    return _generator()

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    result = {}
    try:
        for d in dicts:
            if not isinstance(d, dict):
                raise TypeError(f"All items must be dictionaries, got {type(d).__name__}")
            for k, v in d.items():
                if not isinstance(v, (int, float)):
                    raise TypeError(f"Value for key {k!r} must be numeric, got {type(v).__name__}")
                result[k] = result.get(k, 0) + v
    except TypeError:
        raise
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        url_args = {}
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")
    import re
    # Matches {key} or :key (but not :key/...)
    pattern = re.compile(r'\{([^}]+)\}|:([^/]+)')
    def repl(match):
        key = match.group(1) or match.group(2)
        if key not in url_args:
            raise ValueError(f"Missing URL argument: {key}")
        val = url_args[key]
        return '' if val is None else str(val)
    return pattern.sub(repl, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if not isinstance(val, str):
        return False
    stripped = val.strip().lower()
    return stripped in {"none", "null", "nil"}

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser cannot be None")
    # Basic type check: argparse.ArgumentParser instances have a _actions attribute
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    try:
        actions = parser._actions
    except Exception as exc:
        raise TypeError("Failed to access parser actions") from exc
    if not hasattr(actions, "__iter__"):
        raise TypeError("Parser actions are not iterable")
    flags = []
    for action in actions:
        # Some actions may not have option_strings (e.g., positional arguments)
        option_strings = getattr(action, "option_strings", None)
        if not option_strings:
            continue
        # option_strings is usually a list or tuple of strings
        if isinstance(option_strings, (list, tuple)):
            for opt in option_strings:
                if isinstance(opt, str) and opt:
                    flags.append(opt)
        elif isinstance(option_strings, str):
            flags.append(option_strings)
    return " ".join(flags)

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: Modified flow_params dictionary
    """
    # Validate inputs
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key")
    # Convert register_number to string for key usage
    reg_key = str(register_number)

    def _replace_in_obj(obj):
        if isinstance(obj, dict):
            # If the target key exists, replace it
            if register_value in obj:
                obj[reg_key] = obj.pop(register_value)
            # Recurse into nested structures
            for v in obj.values():
                _replace_in_obj(v)
        elif isinstance(obj, list):
            for item in obj:
                _replace_in_obj(item)
        # Other types are ignored

    try:
        _replace_in_obj(flow_params)
    except Exception as e:
        # Log or re-raise with context if needed
        raise RuntimeError(f"Error while replacing register key: {e}") from e

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    def _recurse(c):
        for sub in c.__subclasses__():
            if sub not in result:
                result.add(sub)
                _recurse(sub)
    _recurse(cls)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError("string must be a str")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")

    # Validate alphabet
    if len(alphabet) == 0:
        raise ValueError("alphabet must not be empty")
    for elem in alphabet:
        if not isinstance(elem, str):
            raise TypeError("alphabet elements must be str")
        if len(elem) != 1:
            raise ValueError("alphabet elements must be single characters")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must not contain duplicate characters")

    base = len(alphabet)
    if base == 0:
        raise ValueError("alphabet must contain at least one character")

    # Build mapping from character to its numeric value
    char_to_value = {char: idx for idx, char in enumerate(alphabet)}

    # Empty string is considered invalid
    if string == "":
        raise ValueError("string must not be empty")

    # Handle base 1 (unary) specially
    if base == 1:
        if all(ch == alphabet[0] for ch in string):
            return len(string)
        else:
            raise ValueError("string contains characters not in alphabet")

    # Convert string to integer
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' not in alphabet")
        result = result * base + char_to_value[ch]
    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Validate inputs
    if not isinstance(url, str) or not url:
        raise TypeError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Ensure destination_path is a directory
    try:
        if destination_path.exists():
            if not destination_path.is_dir():
                raise ValueError(f"destination_path {destination_path} exists and is not a directory")
        else:
            destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Failed to prepare destination directory {destination_path}") from exc

    # Download the archive
    try:
        import requests
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to download archive from {url}") from exc

    # Write to a temporary file
    import tempfile
    import os
    tmp_file_path = None
    try:
        with tempfile.NamedTemporaryFile(delete=False) as tmp_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    tmp_file.write(chunk)
            tmp_file_path = Path(tmp_file.name)

        # Extract the archive
        try:
            import tarfile
            with tarfile.open(tmp_file_path, "r:gz") as tar:
                tar.extractall(path=destination_path)
        except Exception as exc:
            raise RuntimeError(f"Failed to extract archive {tmp_file_path}") from exc
    finally:
        # Clean up temporary file
        if tmp_file_path and tmp_file_path.exists():
            try:
                tmp_file_path.unlink()
            except Exception:
                pass

    return destination_path

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        return []

    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError("find_paths must be an iterable of strings")

    result = []
    for item in iterator:
        if not isinstance(item, str):
            raise TypeError(f"find_paths elements must be strings, got {type(item).__name__}")
        # Treat any string containing ':' as an existing pattern; leave it unchanged.
        if ':' in item:
            result.append(item)
        else:
            # Convert a plain fragment into a glob pattern that matches any path containing it.
            result.append(f"sh:**/*{item}*/**")
    return result

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Accept a string as a simple name
    if isinstance(matcher, str):
        name = matcher
        default_provided = False
        default = None
    # Accept a tuple or list with 1 or 2 elements
    elif isinstance(matcher, (tuple, list)):
        if not matcher:
            raise ValueError("matcher must contain at least a variable name")
        if len(matcher) > 2:
            raise ValueError("matcher must contain at most a variable name and an optional default value")
        name = matcher[0]
        if len(matcher) == 2:
            default_provided = True
            default = matcher[1]
        else:
            default_provided = False
            default = None
    else:
        raise TypeError("matcher must be a string, tuple, or list")

    if not isinstance(name, str):
        raise TypeError("variable name must be a string")

    value = os.getenv(name)
    if value is None:
        if default_provided:
            return default
        else:
            raise KeyError(f"Environment variable '{name}' not found and no default provided")
    return value

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if strip:
        pattern = pattern.strip()
    try:
        escaped = re.escape(pattern)
        return re.compile(escaped)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}") from e

def is_ipv4(target):
    """Test if IPv4 address or not."""
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except Exception:
        return False

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Basic type checks
    if graph is None:
        raise TypeError("graph must not be None")
    if not hasattr(graph, "subjects") or not hasattr(graph, "objects"):
        raise TypeError("graph must be an rdflib.Graph (or compatible)")
    if prop is None:
        raise TypeError("prop must not be None")

    try:
        # All subjects that appear as a child
        subjects = set(graph.subjects(prop, None))
        # All objects that appear as a parent
        objects = set(graph.objects(prop, None))
    except Exception as exc:
        raise RuntimeError(f"Failed to iterate over graph: {exc}") from exc

    # Roots are subjects that never appear as an object
    computed_roots: Set["Node"] = subjects - objects

    # If a specific set of roots was supplied, intersect with it
    if roots is not None:
        if not isinstance(roots, set):
            try:
                roots = set(roots)
            except Exception as exc:
                raise TypeError("roots must be a set of nodes") from exc
        computed_roots &= roots

    return computed_roots

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            yaml_str = yaml.safe_dump(obj, default_flow_style=False)
        else:
            yaml_str = yaml.dump(obj, Dumper=dumper, default_flow_style=False)
    except Exception as exc:
        raise ValueError("Failed to dump object to YAML string: %s" % exc)
    if isinstance(yaml_str, bytes):
        try:
            yaml_str = yaml_str.decode('utf-8')
        except Exception as exc:
            raise ValueError("Failed to decode YAML string: %s" % exc)
    return yaml_str

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError(f"shape must be a tuple or list of integers, got {type(shape).__name__}")
    # Convert to tuple
    shape_tuple = tuple(shape)
    # Ensure all dimensions are integers and non-negative
    for dim in shape_tuple:
        if not isinstance(dim, int):
            raise TypeError(f"All dimensions in shape must be integers, got {type(dim).__name__}")
        if dim < 0:
            raise ValueError(f"All dimensions in shape must be non-negative, got {dim}")
    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"dtype must be a valid numpy dtype, got {dtype}") from exc
    # Create and return the array
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape_tuple} and dtype {dtype_obj}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    Returns the probability density function value(s) at x.
    """
    if x is None:
        raise ValueError("Input x cannot be None.")
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input x must be a number or array-like of numbers.") from e
    mu = 0.2
    sigma = 0.1
    prefactor = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exponent = -((x_arr - mu) ** 2) / (2 * sigma ** 2)
    return prefactor * np.exp(exponent)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    # Use built-in modules via __import__ to avoid explicit import statements
    json = __import__('json')
    os = __import__('os')
    re = __import__('re')
    logging = __import__('logging')

    configs = {}
    error_records = []

    # Ensure config_filenames is iterable
    try:
        filenames = list(config_filenames)
    except Exception:
        # If not iterable, treat as single filename
        filenames = [config_filenames]

    for filename in filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            # Parse JSON
            parsed = json.loads(content)
            if not isinstance(parsed, dict):
                raise ValueError(f"Configuration in {filename} is not a JSON object")
            # Resolve environment variables if requested
            if resolve_env:
                def resolve(obj):
                    if isinstance(obj, dict):
                        return {k: resolve(v) for k, v in obj.items()}
                    elif isinstance(obj, list):
                        return [resolve(v) for v in obj]
                    elif isinstance(obj, str):
                        # Replace ${VAR} with environment variable
                        def repl(match):
                            var = match.group(1)
                            return os.getenv(var, match.group(0))
                        return re.sub(r'\$\{([^}]+)\}', repl, obj)
                    else:
                        return obj
                parsed = resolve(parsed)
            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                parsed.update(overrides)
            configs[filename] = parsed
        except FileNotFoundError as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"File not found: {filename}",
                args=(),
                exc_info=None
            )
            error_records.append(record)
        except json.JSONDecodeError as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"JSON decode error in {filename}: {e.msg}",
                args=(),
                exc_info=None
            )
            error_records.append(record)
        except Exception as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Error processing {filename}: {str(e)}",
                args=(),
                exc_info=None
            )
            error_records.append(record)

    return configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except Exception as exc:
            raise ValueError(f"Failed to encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise TypeError("values must be an iterable of strings, got None")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError(f"values must be an iterable of strings, got {type(values).__name__}")
    cleaned = []
    for v in iterator:
        if not isinstance(v, str):
            raise TypeError(f"Bookmark value must be a string, got {type(v).__name__}")
        cleaned.append(v)
    return cls(cleaned)

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale is requested
    if other is None:
        return getattr(self, "_scale", None)

    # Validate that the new scale is numeric
    try:
        new_scale = float(other)
    except Exception as exc:
        raise TypeError("Scale must be a numeric value") from exc

    # Ensure the current scale is known and non‑zero
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    # Compute the scaling factor
    factor = new_scale / current_scale

    # Import numpy lazily; fall back to pure Python if unavailable
    try:
        import numpy as np
    except Exception:
        np = None

    # Rescale the last coordinate of the data
    fields = getattr(self, "_fields", None)
    if not fields:
        raise ValueError("Graph has no fields to rescale")
    last_field = fields[-1]

    data = getattr(self, "_data", None)
    if data is None:
        raise ValueError("Graph has no data to rescale")

    if np is not None and isinstance(data, np.ndarray):
        # Assume the last column corresponds to the last field
        data[:, -1] = data[:, -1] * factor
    elif isinstance(data, dict):
        # Data stored as a dict of field → array
        if last_field in data:
            arr = data[last_field]
            if np is not None:
                data[last_field] = np.array(arr, dtype=float) * factor
            else:
                data[last_field] = [float(v) * factor for v in arr]
        else:
            raise KeyError(f"Field '{last_field}' not found in data")
    else:
        # Fallback: try to treat data as a list of rows
        try:
            new_rows = []
            for row in data:
                if not isinstance(row, (list, tuple)):
                    raise TypeError("Data rows must be list or tuple")
                new_row = list(row)
                new_row[-1] = float(row[-1]) * factor
                new_rows.append(new_row)
            setattr(self, "_data", new_rows)
        except Exception as exc:
            raise TypeError("Unsupported data format for rescaling") from exc

    # Rescale the corresponding errors, if any
    errors = getattr(self, "_errors", None)
    if errors is not None:
        if np is not None and isinstance(errors, np.ndarray):
            errors[:, -1] = errors[:, -1] * factor
        elif isinstance(errors, dict):
            if last_field in errors:
                arr = errors[last_field]
                if np is not None:
                    errors[last_field] = np.array(arr, dtype=float) * factor
                else:
                    errors[last_field] = [float(v) * factor for v in arr]
        else:
            # Fallback for list of rows
            try:
                new_err_rows = []
                for row in errors:
                    if not isinstance(row, (list, tuple)):
                        raise TypeError("Error rows must be list or tuple")
                    new_row = list(row)
                    new_row[-1] = float(row[-1]) * factor
                    new_err_rows.append(new_row)
                setattr(self, "_errors", new_err_rows)
            except Exception:
                # If we cannot rescale errors, ignore silently
                pass

    # Update the stored scale
    setattr(self, "_scale", new_scale)
    return None

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Import zope.interface components lazily to avoid top-level imports
    try:
        from zope.interface import Invalid, providedBy
    except Exception as exc:
        raise Invalid(f"Unable to import zope.interface components: {exc}")

    errors = []

    # 1. Check that candidate claims to provide iface (unless tentative)
    if not tentative:
        try:
            if not providedBy(candidate).provides(iface):
                errors.append(
                    f"Candidate {candidate!r} does not claim to provide interface {iface!r}"
                )
        except Exception as exc:
            errors.append(
                f"Error checking providedBy for candidate {candidate!r}: {exc}"
            )

    # 2. Check required methods
    try:
        required_methods = iface.getRequiredMethods()
    except Exception as exc:
        raise Invalid(f"Unable to get required methods from interface {iface!r}: {exc}")

    for name in required_methods:
        if not hasattr(candidate, name):
            errors.append(
                f"Candidate {candidate!r} is missing required method '{name}' from interface {iface!r}"
            )
        else:
            attr = getattr(candidate, name)
            if not callable(attr):
                errors.append(
                    f"Attribute '{name}' of candidate {candidate!r} is not callable as required by interface {iface!r}"
                )

    # 3. Check required attributes
    try:
        required_attrs = iface.getRequiredAttributes()
    except Exception as exc:
        raise Invalid(f"Unable to get required attributes from interface {iface!r}: {exc}")

    for name in required_attrs:
        if not hasattr(candidate, name):
            errors.append(
                f"Candidate {candidate!r} is missing required attribute '{name}' from interface {iface!r}"
            )

    # 4. Raise errors if any
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("; ".join(errors))

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases
    if not isinstance(bases, (tuple, list)):
        raise TypeError("bases must be a tuple or list of classes")
    # If no bases, default to type
    if not bases:
        if explicit_mc is None:
            return type
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class")
        return explicit_mc
    # Validate each base
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a class")
    # Determine metaclasses of bases
    base_mcs = [type(base) for base in bases]
    # If explicit metaclass is provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class")
        # Ensure explicit metaclass is a subclass of all base metaclasses
        for bm in base_mcs:
            if not issubclass(explicit_mc, bm):
                raise TypeError(
                    f"metaclass conflict: {explicit_mc.__name__} is not a subclass of {bm.__name__}"
                )
        return explicit_mc
    # No explicit metaclass: find the most derived metaclass
    candidate = base_mcs[0]
    for bm in base_mcs[1:]:
        if issubclass(candidate, bm):
            continue
        elif issubclass(bm, candidate):
            candidate = bm
        else:
            raise TypeError(
                "metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases"
            )
    return candidate

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    # Key exists; remove it
    try:
        del self[key]
    except Exception as exc:
        # In case deletion fails, re-raise with a clear message
        raise RuntimeError(f"Failed to delete key {key!r}") from exc
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Attempt to locate the underlying ordered mapping that tracks usage.
    # Common attribute names for an LRU cache implementation are `_cache` or `cache`.
    cache_attr = None
    for attr_name in ("_cache", "cache"):
        if hasattr(self, attr_name):
            cache_attr = getattr(self, attr_name)
            break
    if cache_attr is None:
        raise AttributeError("No cache attribute found on the instance.")
    # Ensure the cache supports the OrderedDict popitem(last=False) interface.
    if not hasattr(cache_attr, "popitem"):
        raise TypeError("Cache attribute does not support popitem operation.")
    try:
        # Pop the first item (least recently used) from the ordered mapping.
        return cache_attr.popitem(last=False)
    except TypeError:
        # If the underlying cache is a plain dict (Python 3.7+ preserves insertion order),
        # we can still pop the first item by converting to a list of items.
        try:
            items = list(cache_attr.items())
            if not items:
                raise KeyError("Cache is empty.")
            key, value = items[0]
            del cache_attr[key]
            return key, value
        except Exception as exc:
            raise RuntimeError(f"Failed to pop least recently used item: {exc}") from exc
    except KeyError:
        # The cache is empty.
        raise KeyError("Cache is empty.") from None
    except Exception as exc:
        # Catch any other unexpected errors and wrap them.
        raise RuntimeError(f"Unexpected error during popitem: {exc}") from exc

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Ensure the object behaves like a mapping
    if not hasattr(self, "items") or not hasattr(self, "__delitem__"):
        raise TypeError("popitem() requires a mapping-like object")
    # Attempt to retrieve the most recently used item
    try:
        key, value = next(reversed(self.items()))
    except TypeError:
        # The items view is not reversible; fall back to linear scan
        key = value = None
        for k, v in self.items():
            key, value = k, v
        if key is None:
            raise KeyError("popitem(): dictionary is empty")
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty")
    # Remove the item from the mapping
    try:
        del self[key]
    except Exception as exc:
        raise RuntimeError(f"Failed to delete key {key}") from exc
    return key, value

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        # Retrieve the converter class from the _converting module
        converter_cls = getattr(_converting, "_Converter", None)
        if converter_cls is None:
            raise AttributeError("Converter class '_Converter' not found in _converting module")
        if not callable(converter_cls):
            raise TypeError(f"Expected '_Converter' to be callable, got {type(converter_cls).__name__}")
        # Instantiate and return the converter
        return converter_cls()
    except Exception as exc:
        # Wrap any exception in a RuntimeError to provide a clear error message
        raise RuntimeError("Failed to create parameter style converter") from exc

def fromutc(self, dt):
    """
    Given a timezone-aware datetime in UTC, calculates a timezone-aware datetime in this timezone.

    Since this is the one time that we *know* we have an unambiguous datetime object, we take this opportunity to determine whether the datetime is ambiguous and in a "fold" state (e.g. if it's the first occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object that must be in UTC.
    :return:
        A timezone-aware :class:`datetime.datetime` object in this timezone.
    """
    # Validate input type
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime instance")
    # Ensure dt is timezone-aware
    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")
    # Ensure dt is in UTC
    try:
        utc_offset = dt.tzinfo.utcoffset(dt)
    except Exception as exc:
        raise ValueError("dt.tzinfo.utcoffset(dt) failed") from exc
    if utc_offset is None or utc_offset != datetime.timedelta(0):
        raise ValueError("dt must be in UTC")
    # Determine the offset for this timezone
    try:
        offset = self.utcoffset(dt)
    except Exception as exc:
        raise ValueError("cannot determine offset for dt") from exc
    if offset is None:
        raise ValueError("offset for dt is None")
    # Compute the local datetime
    try:
        local_dt = dt + offset
    except Exception as exc:
        raise ValueError("failed to compute local datetime") from exc
    # Attach this timezone
    try:
        local_dt = local_dt.replace(tzinfo=self)
    except Exception as exc:
        raise ValueError("failed to set tzinfo on local datetime") from exc
    # Propagate fold information if present
    if hasattr(dt, "fold"):
        try:
            local_dt = local_dt.replace(fold=dt.fold)
        except Exception:
            # If replace fails for fold, ignore silently
            pass
    return local_dt

def identify_request(request):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Helper to get attribute or dict key
        def get_value(obj, key):
            if isinstance(obj, dict):
                return obj.get(key)
            return getattr(obj, key, None)

        # Check for public message
        public_msg = get_value(request, 'public_message')
        if public_msg is not None:
            return True

        # Check for private message
        private_msg = get_value(request, 'private_message')
        if private_msg is not None:
            return True

        # Check for legacy payload
        payload = get_value(request, 'payload')
        if payload is not None:
            # If payload is a dict, look for a 'legacy' key
            if isinstance(payload, dict):
                if 'legacy' in payload:
                    return True
            else:
                # If payload is an object, look for a 'legacy' attribute
                if getattr(payload, 'legacy', None) is not None:
                    return True

    except Exception:
        # Any unexpected error should result in a non-Diaspora identification
        return False

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Handle None or non-object inputs
        if request is None:
            return False

        # Extract path and headers from dict-like or object-like request
        if isinstance(request, dict):
            path = request.get("path", "")
            headers = request.get("headers", {})
        else:
            path = getattr(request, "path", "")
            headers = getattr(request, "headers", {})

        # Normalize headers to a dict if possible
        if not isinstance(headers, dict):
            # Try to convert common header objects to dict
            try:
                headers = dict(headers)
            except Exception:
                headers = {}

        # Check for typical Matrix request path prefix
        if isinstance(path, str) and path.startswith("/_matrix/"):
            return True

        # Check for typical Matrix request headers
        if isinstance(headers, dict):
            # Content-Type check (case-insensitive)
            content_type = headers.get("Content-Type") or headers.get("content-type")
            if isinstance(content_type, str) and content_type.lower() == "application/json":
                # Optional: look for a Matrix-specific header
                if "X-Matrix-Request" in headers or "x-matrix-request" in headers:
                    return True

        # Fallback: check if request body contains Matrix-specific keys
        if hasattr(request, "json"):
            body = getattr(request, "json")
            if isinstance(body, dict) and "type" in body:
                # Common Matrix event types start with "m."
                if isinstance(body["type"], str) and body["type"].startswith("m."):
                    return True

        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function accepts a datetime instance and returns an ISO‑8601
    string.  Naïve datetimes are treated as UTC and suffixed with
    ``Z``.  Time‑zone aware datetimes are formatted with their
    offset.  The function is tolerant of older Python versions that
    do not support the ``timespec`` argument to ``isoformat``.
    """
    if dt is None:
        raise TypeError("dt cannot be None")
    # Try the modern ISO format with seconds precision
    try:
        s = dt.isoformat(timespec='seconds')
    except Exception:
        # Fallback for older Python versions
        try:
            s = dt.strftime('%Y-%m-%dT%H:%M:%S')
        except Exception:
            raise TypeError("dt must be a datetime-like object")
        # Append timezone information if present
        if hasattr(dt, 'tzinfo') and dt.tzinfo is not None:
            offset = dt.strftime('%z')
            if offset:
                # Convert +HHMM to +HH:MM
                s += offset[:3] + ':' + offset[3:]
        else:
            # Naïve datetime – assume UTC
            s += 'Z'
    else:
        # If isoformat returned a string without a timezone and the
        # datetime is naïve, add the UTC designator.
        if not hasattr(dt, 'tzinfo') or dt.tzinfo is None:
            if not s.endswith('Z'):
                s += 'Z'
    return s

from typing import Optional

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    if not isinstance(url, str) or not url:
        return None
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Accept only lowercase letters, digits, and hyphens.
    # No leading/trailing hyphens, no consecutive hyphens.
    # Return False for non-string or empty input.
    if not isinstance(tag, str) or not tag:
        return False
    try:
        import re
        pattern = re.compile(r'^[a-z0-9]+(?:-[a-z0-9]+)*$')
        return bool(pattern.match(tag))
    except Exception:
        # In case of any unexpected error, consider the tag invalid.
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # Ensure the node looks like an ElementTree element
    if not hasattr(node, "tag"):
        raise TypeError("node must be an ElementTree.Element or similar")
    result = {}
    try:
        for child in node:
            # Only include objects that look like elements
            if hasattr(child, "tag"):
                result[child.tag] = child
    except TypeError as exc:
        raise TypeError("node must be iterable over child elements") from exc
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate url
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    url = url.strip()
    if not url:
        raise ValueError("url cannot be empty")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Determine the document path
    if document_path is None:
        path = "/nodeinfo/2.0"
    else:
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string")
        document_path = document_path.strip()
        if not document_path:
            path = "/nodeinfo/2.0"
        else:
            if not document_path.startswith("/"):
                raise ValueError("document_path must start with '/'")
            path = document_path

    # Build the full URL to the NodeInfo document
    base = url.rstrip("/")
    full_url = base + path

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": full_url
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Basic input validation
    if public_key is None or doc is None or signature is None:
        return False
    # Ensure inputs are strings
    try:
        if isinstance(public_key, bytes):
            public_key = public_key.decode('utf-8')
        if isinstance(doc, bytes):
            doc = doc.decode('utf-8')
        if isinstance(signature, bytes):
            signature = signature.decode('utf-8')
    except Exception:
        return False

    # Attempt to import required libraries
    try:
        import lxml.etree as ET
        import xmlsec
    except Exception:
        # Required libraries not available
        return False

    # Parse the XML document
    try:
        root = ET.fromstring(doc)
    except ET.XMLSyntaxError:
        return False

    # Find the Signature node
    try:
        signature_node = xmlsec.tree.find_node(root, xmlsec.Node.SIGNATURE)
    except Exception:
        return False
    if signature_node is None:
        return False

    # Extract the SignatureValue from the XML
    try:
        ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}
        sig_value_elem = signature_node.find('.//ds:SignatureValue', namespaces=ns)
        if sig_value_elem is None or sig_value_elem.text is None:
            return False
        xml_sig_value = sig_value_elem.text.strip()
    except Exception:
        return False

    # Compare provided signature with the one in the XML
    if xml_sig_value != signature:
        return False

    # Load the public key
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception:
        return False

    # Verify the signature
    try:
        ctx = xmlsec.SignatureContext()
        ctx.key = key
        ctx.verify(signature_node)
        return True
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document or not isinstance(document, str):
        return {}
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if isinstance(data, dict):
            result: Dict = {}
            # Extract subject
            subject = data.get("subject")
            if subject:
                result["subject"] = subject
            # Extract aliases
            aliases = data.get("aliases")
            if isinstance(aliases, list):
                result["aliases"] = aliases
            # Extract links
            links = data.get("links")
            if isinstance(links, list):
                result["links"] = links
            return result
    except Exception:
        pass  # fall back to XML parsing

    # Try XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        ns = {}
        if root.tag.startswith("{"):
            uri, _, _ = root.tag[1:].partition("}")
            ns["ns"] = uri
            subject_elem = root.find("ns:Subject", ns)
            alias_elems = root.findall("ns:Alias", ns)
            link_elems = root.findall("ns:Link", ns)
        else:
            subject_elem = root.find("Subject")
            alias_elems = root.findall("Alias")
            link_elems = root.findall("Link")

        result: Dict = {}
        if subject_elem is not None and subject_elem.text:
            result["subject"] = subject_elem.text

        aliases = [a.text for a in alias_elems if a.text]
        if aliases:
            result["aliases"] = aliases

        links = []
        for l in link_elems:
            link_dict = {}
            for attr, val in l.attrib.items():
                link_dict[attr] = val
            if link_dict:
                links.append(link_dict)
        if links:
            result["links"] = links

        return result
    except Exception:
        # If parsing fails, return empty dict
        return {}

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate input
    if not isinstance(handle, str):
        return {}
    handle = handle.strip()
    if not handle:
        return {}
    # Remove optional 'acct:' prefix
    if handle.lower().startswith('acct:'):
        handle = handle[5:]
    if '@' not in handle:
        return {}
    local, domain = handle.split('@', 1)
    if not local or not domain:
        return {}
    # Build the webfinger URL
    try:
        import urllib.parse
        resource = f'acct:{handle}'
        query = urllib.parse.urlencode({'resource': resource})
        url = f'https://{domain}/.well-known/webfinger?{query}'
    except Exception:
        return {}
    # Fetch and parse the JSON response
    try:
        import urllib.request
        import urllib.error
        import json
        req = urllib.request.Request(url, headers={'User-Agent': 'PythonWebFinger/1.0'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                return {}
            data = resp.read().decode('utf-8')
            parsed = json.loads(data)
            if isinstance(parsed, dict):
                return parsed
            return {}
    except (urllib.error.HTTPError, urllib.error.URLError, json.JSONDecodeError, ValueError, Exception):
        return {}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.request``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        # Basic validation
        if not isinstance(url, str) or not url.strip():
            raise ValueError("URL must be a non-empty string")
        if timeout is None or not isinstance(timeout, (int, float)):
            timeout = 10
        if method is None or not isinstance(method, str):
            method = "post"

        # Send the request
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)

        # Return status code and no error
        return (response.status_code, None)
    except Exception as exc:
        # On any exception, return None for status and the exception instance
        return (None, exc)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if key is None:
        raise TypeError("key must not be None")
    all_keys = [key] + list(keys)
    current = dic
    for k in all_keys[:-1]:
        if k is None:
            raise TypeError("intermediate key must not be None")
        if k not in current:
            current[k] = {}
        else:
            if not isinstance(current[k], dict):
                raise TypeError(f"Intermediate key {k!r} is not a dictionary")
        current = current[k]
    last = all_keys[-1]
    if last is None:
        raise TypeError("last key must not be None")
    current[last] = val
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file paths found in the directories specified by `settings_dirs`.
    If `spec_option` is provided, only files that match the given extension or pattern
    are returned. The function is tolerant to invalid inputs and missing directories.
    """
    # Helper to import os without a top-level import statement
    os = __import__('os')
    result = []

    # Validate settings_dirs
    try:
        dirs_iter = iter(settings_dirs)
    except TypeError:
        # Not iterable, return empty list
        return result

    # Normalize spec_option
    if spec_option is None:
        spec_patterns = None
    else:
        if isinstance(spec_option, str):
            spec_patterns = [spec_option.lower()]
        elif isinstance(spec_option, (list, tuple, set)):
            spec_patterns = [str(p).lower() for p in spec_option]
        else:
            # Unsupported spec_option type, ignore filtering
            spec_patterns = None

    for dir_path in dirs_iter:
        if not isinstance(dir_path, str):
            continue
        try:
            entries = os.listdir(dir_path)
        except (OSError, FileNotFoundError, NotADirectoryError):
            continue
        for entry in entries:
            full_path = os.path.join(dir_path, entry)
            if not os.path.isfile(full_path):
                continue
            if spec_patterns:
                # Check if file ends with any of the patterns
                lower_name = entry.lower()
                if not any(lower_name.endswith(p) for p in spec_patterns):
                    continue
            result.append(full_path)
    return result

