@classmethod
def validate_from_content(cls, spec_content=None):
    """
    Validates that spec (YAML) content has all required fields.

    :param spec_content: content of spec file (YAML string or dict)
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Ensure content is provided
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # Load YAML if content is a string
    if isinstance(spec_content, str):
        try:
            import yaml
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML content: {exc}")
    else:
        data = spec_content

    # After loading, data must be a mapping
    if data is None or not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a mapping (dict)")

    # Define required fields (adjust as needed for the specific spec)
    required_fields = ["name", "version", "description"]

    # Check for missing required fields
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    # Ensure a file path was provided
    if yaml_file is None:
        raise ValueError("yaml_file must be a path to a YAML file")

    # Import yaml lazily to avoid unnecessary dependency if not used
    try:
        import yaml
    except ImportError as exc:
        raise ImportError("PyYAML is required to load YAML files") from exc

    # Read and parse the YAML file
    try:
        with open(yaml_file, "r", encoding="utf-8") as fh:
            data = yaml.safe_load(fh)
    except FileNotFoundError as exc:
        raise IRValidatorException(f"YAML file not found: {yaml_file}") from exc
    except yaml.YAMLError as exc:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {exc}") from exc
    except Exception as exc:
        raise IRValidatorException(f"Unexpected error reading YAML file {yaml_file}: {exc}") from exc

    # Ensure the file contains a mapping (dictionary)
    if not isinstance(data, dict):
        raise IRValidatorException(f"YAML file {yaml_file} does not contain a top-level mapping")

    # Validate required fields if the class defines them
    required_fields = getattr(cls, "REQUIRED_FIELDS", None)
    if required_fields:
        if not hasattr(required_fields, "__iter__"):
            raise TypeError("REQUIRED_FIELDS must be an iterable of field names")
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required field(s) in YAML file {yaml_file}: {', '.join(missing)}"
            )

    return data

