def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Retrieve the spec dictionary; if missing or invalid, treat as empty
        spec = getattr(self, "spec", {})
        if not isinstance(spec, dict):
            raise TypeError("`spec` attribute must be a dictionary")

        # Extract defaults from the spec
        for key, value in spec.items():
            if isinstance(value, dict):
                defaults[key] = value.get("default")
            else:
                # If the spec entry is not a dict, try to fetch a 'default' attribute
                defaults[key] = getattr(value, "default", None)

        # Override with explicit defaults if provided
        explicit_defaults = getattr(self, "defaults", {})
        if isinstance(explicit_defaults, dict):
            defaults.update(explicit_defaults)

        # Override with environment or other source values if provided
        env_values = getattr(self, "env", {})
        if isinstance(env_values, dict):
            for key, val in env_values.items():
                defaults[key] = val

    except Exception as exc:
        # Wrap any exception in a RuntimeError to provide context
        raise RuntimeError(f"Failed to resolve spec defaults: {exc}") from exc

    return defaults

