def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Handle None inputs gracefully
    if cli_args is None:
        cli_args = {}
    if answer_file_args is None:
        answer_file_args = {}

    # Validate that inputs are dictionaries
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve the set of deprecated arguments, if defined on the instance
    deprecated = getattr(self, "DEPRECATED_ARGS", set())
    if not isinstance(deprecated, (set, list, tuple)):
        deprecated = set()
    else:
        deprecated = set(deprecated)

    # Combine keys from both sources to avoid duplicate warnings
    all_keys = set(cli_args.keys()) | set(answer_file_args.keys())

    for key in all_keys:
        # Skip non-string keys
        if not isinstance(key, str):
            continue
        if key in deprecated:
            sources = []
            if key in cli_args:
                sources.append("CLI")
            if key in answer_file_args:
                sources.append("answer file")
            source_str = " and ".join(sources) if len(sources) > 1 else sources[0]
            print(f"Deprecated argument '{key}' found in {source_str} arguments.")

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    command_name = command_name.strip()
    if not command_name:
        return []

    # Retrieve the options dictionary from the instance
    options_dict = getattr(self, "parser_options", {})
    if not isinstance(options_dict, dict):
        return []

    # Try an exact match first
    if command_name in options_dict:
        opts = options_dict[command_name]
    else:
        # Fallback to case‑insensitive match
        opts = None
        for key, value in options_dict.items():
            if key.lower() == command_name.lower():
                opts = value
                break

    # Ensure the result is a list
    if isinstance(opts, list):
        return opts
    return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")
    if command_name == "" or argument_name == "":
        raise ValueError("command_name and argument_name cannot be empty")

    # Retrieve the commands mapping from the instance
    commands = getattr(self, "commands", None)
    if commands is None:
        raise AttributeError("The instance does not have a 'commands' attribute")

    # Attempt to fetch the command object
    try:
        cmd_obj = commands[command_name]
    except (KeyError, TypeError):
        # Command not found or commands is not subscriptable
        return None

    # Retrieve the options mapping from the command object
    options = getattr(cmd_obj, "options", None)
    if options is None:
        return None

    # Attempt to fetch the option specification
    try:
        spec = options[argument_name]
    except (KeyError, TypeError):
        # Option not found or options is not subscriptable
        return None

    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_keys = []
    try:
        if args is None:
            return silent_keys
        # Determine iterable of (name, value) pairs
        if isinstance(args, dict):
            items = args.items()
        elif isinstance(args, (list, tuple)):
            items = []
            for item in args:
                if isinstance(item, tuple) and len(item) == 2:
                    items.append(item)
        else:
            return silent_keys
        for key, value in items:
            # None values are considered silent
            if value is None:
                silent_keys.append(key)
                continue
            # Empty strings or bytes
            if isinstance(value, (str, bytes)):
                if value == '':
                    silent_keys.append(key)
                continue
            # Empty collections
            if isinstance(value, (list, tuple, set, dict)):
                try:
                    if len(value) == 0:
                        silent_keys.append(key)
                except Exception:
                    pass
                continue
            # Other types are not considered silent
    except Exception:
        # On any unexpected error, return what has been collected so far
        pass
    return silent_keys

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    # Ensure args is a mapping for eval context
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}
    for opt in options_spec:
        # Retrieve option name
        name = None
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)
        if not name or cond is None:
            continue
        try:
            if callable(cond):
                if cond(args):
                    required.append(name)
            elif isinstance(cond, str):
                # Evaluate string condition in the context of args
                if eval(cond, {}, args):
                    required.append(name)
        except Exception:
            # Skip options whose condition cannot be evaluated
            continue
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Retrieve the mapping of argument names to maximum allowed lengths.
    # If the attribute does not exist or is not a dict, treat as no limits.
    max_lengths = getattr(self, "max_lengths", {})
    if not isinstance(max_lengths, dict):
        max_lengths = {}

    for key, value in args.items():
        # Skip arguments that have no length restriction
        if key not in max_lengths:
            continue

        max_len = max_lengths[key]
        # Skip if the maximum length is not a positive integer
        if not isinstance(max_len, int) or max_len < 0:
            continue

        # Skip None values (treated as length 0)
        if value is None:
            continue

        try:
            length = len(value)
        except TypeError:
            # If the value has no length, skip the check
            continue

        if length > max_len:
            raise ValueError(
                f"Argument '{key}' length {length} exceeds maximum allowed {max_len}"
            )

    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is provided
    if args is None:
        raise TypeError("args cannot be None")

    # Convert Namespace or object with attributes to a dict
    if isinstance(args, dict):
        args_dict = args
    elif hasattr(args, "__dict__"):
        args_dict = vars(args)
    else:
        raise TypeError("args must be a dict or an object with attributes")

    # Ensure the instance has a _choices mapping
    if not hasattr(self, "_choices"):
        raise AttributeError("The object does not have a '_choices' attribute for validation")
    choices_map = getattr(self, "_choices")
    if not isinstance(choices_map, dict):
        raise TypeError("self._choices must be a dict mapping argument names to allowed values")

    # Validate each argument against its allowed choices
    for key, value in args_dict.items():
        if key not in choices_map:
            # No choices defined for this argument; skip validation
            continue

        allowed = choices_map[key]
        if allowed is None:
            # No specific choices to validate against
            continue

        # If allowed is a callable, attempt to retrieve the actual choices
        if callable(allowed):
            try:
                allowed = allowed()
            except Exception as exc:
                raise ValueError(f"Failed to obtain allowed choices for argument '{key}': {exc}") from exc

        # Normalize allowed to an iterable of values
        if isinstance(allowed, (list, tuple, set)):
            allowed_iter = allowed
        else:
            # Treat a single value as a one-element iterable
            allowed_iter = [allowed]

        # If the value itself is an iterable (but not a string), validate each element
        if isinstance(value, (list, tuple, set)) and not isinstance(value, str):
            for v in value:
                if v not in allowed_iter:
                    raise ValueError(
                        f"Invalid value for argument '{key}': {v}. "
                        f"Expected one of {list(allowed_iter)}."
                    )
        else:
            if value not in allowed_iter:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Expected one of {list(allowed_iter)}."
                )
    # If all checks pass, the method completes without error.

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Expected to be a dictionary where each key is the argument name
                 and each value is either a dictionary with keys 'value', 'min', 'max' or a tuple/list
                 of the form (value, min, max). All numeric values are validated to be within the
                 inclusive range [min, max]. Raises ValueError if any argument is out of bounds or
                 if the input format is invalid. Returns True if all arguments are valid.
    """
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of arguments")

    for name, arg in args.items():
        try:
            # Extract value, min, max depending on the format
            if isinstance(arg, dict):
                value = arg.get("value")
                min_val = arg.get("min")
                max_val = arg.get("max")
            elif isinstance(arg, (list, tuple)) and len(arg) == 3:
                value, min_val, max_val = arg
            else:
                raise ValueError(f"Argument '{name}' must be a dict or a 3-element tuple/list")

            # Basic presence checks
            if value is None or min_val is None or max_val is None:
                raise ValueError(f"Argument '{name}' is missing 'value', 'min', or 'max'")

            # Type checks
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for argument '{name}' must be numeric")
            if not isinstance(min_val, (int, float)):
                raise TypeError(f"Min for argument '{name}' must be numeric")
            if not isinstance(max_val, (int, float)):
                raise TypeError(f"Max for argument '{name}' must be numeric")

            # Logical checks
            if min_val > max_val:
                raise ValueError(f"Min greater than max for argument '{name}'")
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument '{name}' with value {value} is out of bounds [{min_val}, {max_val}]"
                )
        except Exception as exc:
            # Re-raise with context
            raise ValueError(f"Invalid argument '{name}': {exc}") from exc

    return True

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Define prefixes that identify control arguments
    control_prefixes = ("control_", "control-", "ir_", "ir-")
    # If args is None or empty, return empty dicts
    if not args:
        return {}, {}
    # If args is already a dict, split keys accordingly
    if isinstance(args, dict):
        control_args = {}
        nested_args = {}
        for key, value in args.items():
            if key.startswith(control_prefixes):
                control_args[key] = value
            else:
                nested_args[key] = value
        return control_args, nested_args
    # Ensure args is a list or tuple
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list, tuple, or dict")
    control_args = {}
    nested_args = {}
    i = 0
    while i < len(args):
        arg = args[i]
        # Skip non-string items
        if not isinstance(arg, str):
            i += 1
            continue
        # Handle long options starting with '--'
        if arg.startswith("--"):
            # Strip leading '--'
            key_val = arg[2:]
            if "=" in key_val:
                key, val = key_val.split("=", 1)
            else:
                key = key_val
                # Check if next item is a value (doesn't start with '-')
                if i + 1 < len(args) and not args[i + 1].startswith("-"):
                    val = args[i + 1]
                    i += 1  # Skip the value in next iteration
                else:
                    val = True  # flag without explicit value
            # Normalize key (remove leading dashes if any)
            key = key.lstrip("-")
            if key.startswith(control_prefixes):
                control_args[key] = val
            else:
                nested_args[key] = val
        # Handle short options starting with single '-'
        elif arg.startswith("-") and not arg.startswith("--"):
            # Treat as flag; value is True
            key = arg.lstrip("-")
            if key.startswith(control_prefixes):
                control_args[key] = True
            else:
                nested_args[key] = True
        else:
            # Positional argument or unrecognized format; ignore or store as flag
            # Here we treat it as a flag with value True
            key = arg
            if key.startswith(control_prefixes):
                control_args[key] = True
            else:
                nested_args[key] = True
        i += 1
    return control_args, nested_args

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import os

    # Helper to log messages if the plugin provides a log method
    def _log(msg):
        if hasattr(ir_plugin, "log"):
            try:
                ir_plugin.log(msg)
            except Exception:
                pass
        else:
            # Fallback to simple print
            print(msg)

    # Resolve the playbook path relative to the workspace if possible
    workspace_path = None
    if hasattr(ir_workspace, "path"):
        workspace_path = ir_workspace.path
    elif hasattr(ir_workspace, "root"):
        workspace_path = ir_workspace.root
    elif hasattr(ir_workspace, "workspace_path"):
        workspace_path = ir_workspace.workspace_path

    if workspace_path:
        playbook_full_path = os.path.join(workspace_path, playbook_path)
    else:
        playbook_full_path = playbook_path

    # Build the ansible-playbook command
    cmd = ["ansible-playbook", playbook_full_path]

    # Verbosity
    if verbose:
        try:
            v_level = int(verbose)
            if v_level > 0:
                cmd.append("-" + "v" * v_level)
        except Exception:
            _log(f"Invalid verbosity level '{verbose}', ignoring.")

    # Extra vars
    if extra_vars:
        try:
            json_str = json.dumps(extra_vars)
            cmd.extend(["--extra-vars", json_str])
        except Exception as e:
            _log(f"Failed to serialize extra_vars: {e}")

    # Additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(key, str) and key.startswith("--"):
                flag = key
            else:
                flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # if False, skip adding the flag
            elif isinstance(value, (list, tuple)):
                # For list values, add each item separately
                for item in value:
                    cmd.extend([flag, str(item)])
            else:
                cmd.extend([flag, str(value)])

    _log(f"Running command: {' '.join(cmd)}")

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=workspace_path if workspace_path else None,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. Ensure Ansible is installed.")
    except Exception as e:
        raise RuntimeError(f"Error running ansible-playbook: {e}")

    # Log output
    if result.stdout:
        _log(f"STDOUT:\n{result.stdout}")
    if result.stderr:
        _log(f"STDERR:\n{result.stderr}")

    # Return a dictionary with the result details
    return {
        "returncode": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr,
    }

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Helper to safely import modules
    def _import(name):
        try:
            return __import__(name)
        except Exception:
            return None

    os = _import('os')
    json = _import('json')
    if os is None or json is None:
        return {}

    # Normalize plugin_dir to string
    try:
        plugin_dir_str = str(plugin_dir)
    except Exception:
        return {}

    if not plugin_dir_str:
        return {}

    # Ensure the directory exists
    try:
        if not os.path.isdir(plugin_dir_str):
            return {}
    except Exception:
        return {}

    # Look for plugin.json file
    spec_path = os.path.join(plugin_dir_str, 'plugin.json')
    if not os.path.isfile(spec_path):
        return {}

    # Read and parse JSON
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            content = f.read()
        data = json.loads(content)
    except Exception:
        return {}

    if not isinstance(data, dict):
        return {}

    # Flatten nested dictionaries
    def _flatten(d, parent_key=''):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(data)
